import{_ as t,o as r,c as n,Q as o}from"./chunks/framework.48927342.js";const k=JSON.parse('{"title":"Module 4: 购物与食物","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/modules/maltese-module4-analysis.md","filePath":"zh/more/maltese/modules/maltese-module4-analysis.md"}'),s={name:"zh/more/maltese/modules/maltese-module4-analysis.md"},g=o('<h1 id="module-4-购物与食物" tabindex="-1">Module 4: 购物与食物 <a class="header-anchor" href="#module-4-购物与食物" aria-label="Permalink to &quot;Module 4: 购物与食物&quot;">​</a></h1><p><strong>Ix-xiri u l-ikel — Shopping and Food — 购物与食物</strong></p><h2 id="主题理解" tabindex="-1">主题理解 <a class="header-anchor" href="#主题理解" aria-label="Permalink to &quot;主题理解&quot;">​</a></h2><table><thead><tr><th>原文</th><th>中文与逐词／短语解析</th></tr></thead><tbody><tr><td>Ix-xiri u l-ikel</td><td>购物与食物。<br><strong>Module 4</strong> 第四模块<br><strong>ix-xiri</strong> 购物、购买（定冠词发生同化）<br><strong>u</strong> 和<br><strong>l-ikel</strong> 食物、饮食。</td></tr><tr><td>Shopping and Food</td><td>购物与食物。<br><strong>shopping</strong> 购物<br><strong>and</strong> 和<br><strong>food</strong> 食物。</td></tr></tbody></table><hr><h2 id="_1-购物对话逐句解析" tabindex="-1">1 购物对话逐句解析 <a class="header-anchor" href="#_1-购物对话逐句解析" aria-label="Permalink to &quot;1 购物对话逐句解析&quot;">​</a></h2><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Il-Qari – Aqra dan id-djalogu.</td><td>阅读：读这段对话。<br><strong>il-qari</strong> 阅读<br><strong>aqra</strong> 读（命令式）<br><strong>dan</strong> 这一个<br><strong>id-djalogu</strong> 对话。</td></tr><tr><td>Klara marret tixtri mingħand tal-merċa.</td><td>Klara 去杂货店买东西。<br><strong>Klara</strong> 人名<br><strong>marret</strong> 她去了<br><strong>tixtri</strong> 她买东西<br><strong>mingħand</strong> 从某人／店家那里<br><strong>tal-merċa</strong> 杂货商、杂货店经营者。</td></tr><tr><td>Bonġu Tumas, agħtini kwart perżut jekk jogħġbok.</td><td>早上好，Tumas，请给我四分之一份重量的火腿。<br><strong>bonġu</strong> 早上好／日安<br><strong>Tumas</strong> 人名<br><strong>agħtini</strong> 给我（agħti + -ni）<br><strong>kwart</strong> 四分之一；买散装食品时通常指约 250 克<br><strong>perżut</strong> 火腿<br><strong>jekk jogħġbok</strong> 请（固定礼貌表达）。</td></tr><tr><td>Bonġu Klar, ara ġej.</td><td>早上好，Klara，马上给你。<br><strong>bonġu</strong> 早上好<br><strong>Klar</strong> 对 Klara 的亲切简称<br><strong>ara</strong> 看、你看（口语提示）<br><strong>ġej</strong> 正在来、马上来；这里相当于“这就给你”。</td></tr><tr><td>Għandi bżonn ukoll nofs kwart ġobon tal-qoxra ħamra u ħames mitt gramma ġobon maħkuk.</td><td>我还需要半个四分之一份的红皮奶酪，以及 500 克磨碎的奶酪。<br><strong>għandi bżonn</strong> 我需要<br><strong>ukoll</strong> 也、还<br><strong>nofs kwart</strong> 八分之一；按公斤语境约 125 克<br><strong>ġobon</strong> 奶酪<br><strong>tal-qoxra</strong> 带皮的／外皮为……的<br><strong>ħamra</strong> 红色的（修饰阴性 qoxra）<br><strong>u</strong> 和<br><strong>ħames mitt</strong> 五百<br><strong>gramma</strong> 克<br><strong>ġobon maħkuk</strong> 磨碎的奶酪<br><strong>maħkuk</strong> 磨碎的、擦碎的。</td></tr><tr><td>Kollox sew... xi ħaġa oħra?</td><td>好的……还要别的吗？<br><strong>kollox</strong> 一切<br><strong>sew</strong> 好、妥当<br><strong>xi ħaġa</strong> 某样东西<br><strong>oħra</strong> 另外的（阴性，配 ħaġa）。</td></tr><tr><td>Le dak kollox, x’għandi nagħtik?</td><td>不，就这些，我该给你多少钱？<br><strong>le</strong> 不<br><strong>dak</strong> 那、这些<br><strong>kollox</strong> 全部<br><strong>x’</strong> 什么<br><strong>għandi</strong> 我应该／我有<br><strong>nagħtik</strong> 我给你（购物语境指付款）。</td></tr><tr><td>Tliet ewro u ħamsin ċenteżmu jekk jogħġbok.</td><td>请付三欧元五十分。<br><strong>tliet</strong> 三（名词前形式）<br><strong>ewro</strong> 欧元<br><strong>u</strong> 和<br><strong>ħamsin</strong> 五十<br><strong>ċenteżmu</strong> 分<br><strong>jekk jogħġbok</strong> 请。</td></tr><tr><td>Ħa, hawn għandek erba’ ewro.</td><td>给，这里是四欧元。<br><strong>ħa</strong> 拿着、给你（递东西时）<br><strong>hawn</strong> 这里<br><strong>għandek</strong> 你有、给你<br><strong>erba’</strong> 四（接名词）<br><strong>ewro</strong> 欧元。</td></tr><tr><td>Mela ħamsin ċenteżmu bqija, saħħa!</td><td>那找你五十分，再见！<br><strong>mela</strong> 那么<br><strong>ħamsin ċenteżmu</strong> 五十分<br><strong>bqija</strong> 余下的、找零<br><strong>saħħa</strong> 祝好、再见；字面“健康”。</td></tr><tr><td>Grazzi u l-ġurnata t-tajba.</td><td>谢谢，祝你今天愉快。<br><strong>grazzi</strong> 谢谢<br><strong>u</strong> 和<br><strong>l-ġurnata</strong> 这一天<br><strong>t-tajba</strong> 美好的（阴性）；整句为祝愿语。</td></tr></tbody></table><h3 id="理解题与参考答案" tabindex="-1">理解题与参考答案 <a class="header-anchor" href="#理解题与参考答案" aria-label="Permalink to &quot;理解题与参考答案&quot;">​</a></h3><table><thead><tr><th>题目与答案</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Xi xtrat Klara? — Klara xtrat kwart perżut, nofs kwart ġobon tal-qoxra ħamra u ħames mitt gramma ġobon maħkuk.</td><td>Klara 买了什么？——火腿、红皮奶酪和碎奶酪，用量与对话一致。<br><strong>xi</strong> 什么<br><strong>xtrat</strong> 她买了<br><strong>Klara</strong> 人名<br><strong>kwart / nofs kwart</strong> 四分之一／八分之一<br><strong>perżut</strong> 火腿<br><strong>ġobon tal-qoxra ħamra</strong> 红皮奶酪<br><strong>ħames mitt gramma</strong> 500 克<br><strong>ġobon maħkuk</strong> 碎奶酪。</td></tr><tr><td>Kemm nefqet? — Nefqet tliet ewro u ħamsin ċenteżmu.</td><td>她花了多少？——3.50 欧元。<br><strong>kemm</strong> 多少<br><strong>nefqet</strong> 她花费了<br><strong>tliet ewro</strong> 三欧元<br><strong>u</strong> 加上<br><strong>ħamsin ċenteżmu</strong> 五十分。</td></tr><tr><td>F’din il-kaxxa ikteb kemm tista’ oġġetti li tista’ tixtri mingħand tal-merċa.</td><td>在框里尽可能多地写出能在杂货店购买的物品。<br><strong>f’din il-kaxxa</strong> 在这个框中<br><strong>ikteb</strong> 写<br><strong>kemm tista’</strong> 尽你所能、多写一些<br><strong>oġġetti</strong> 物品<br><strong>li</strong> ……的<br><strong>tista’ tixtri</strong> 你能购买<br><strong>mingħand tal-merċa</strong> 从杂货商那里。</td></tr></tbody></table><p>第 3 题参考清单（每个词一行）：</p><ul><li><strong>ħobż</strong> 面包。</li><li><strong>ħalib</strong> 牛奶。</li><li><strong>ġobon</strong> 奶酪。</li><li><strong>perżut</strong> 火腿。</li><li><strong>bajd</strong> 鸡蛋（集合名词）。</li><li><strong>butir</strong> 黄油。</li><li><strong>dqiq</strong> 面粉。</li><li><strong>zokkor</strong> 糖。</li><li><strong>melħ</strong> 盐。</li><li><strong>żejt</strong> 油。</li><li><strong>ross</strong> 米。</li><li><strong>għaġin</strong> 意面。</li><li><strong>kafè</strong> 咖啡。</li><li><strong>te</strong> 茶。</li><li><strong>gallettini</strong> 饼干。</li></ul><hr><h2 id="_2-第-4-题-蔬果清单" tabindex="-1">2 第 4 题：蔬果清单 <a class="header-anchor" href="#_2-第-4-题-蔬果清单" aria-label="Permalink to &quot;2 第 4 题：蔬果清单&quot;">​</a></h2><p><strong>F’din il-kaxxa ikteb kemm tista’ frott u ħaxix li ssib mingħand tal-ħaxix.</strong></p><p>中文：在框里尽量列出可在蔬果店找到的水果和蔬菜。</p><ul><li><strong>f’din il-kaxxa</strong> 在这个框里。</li><li><strong>ikteb</strong> 写。</li><li><strong>kemm tista’</strong> 尽可能多。</li><li><strong>frott</strong> 水果（集合）。</li><li><strong>u</strong> 和。</li><li><strong>ħaxix</strong> 蔬菜（集合）。</li><li><strong>li ssib</strong> 你找得到的。</li><li><strong>mingħand tal-ħaxix</strong> 从蔬果商那里。</li></ul><p>参考答案：</p><ul><li><strong>tuffieħ</strong> 苹果。</li><li><strong>larinġ</strong> 橙子。</li><li><strong>banana</strong> 香蕉。</li><li><strong>lanġas</strong> 梨。</li><li><strong>għeneb</strong> 葡萄。</li><li><strong>lumi</strong> 柠檬。</li><li><strong>frawli</strong> 草莓。</li><li><strong>patata</strong> 土豆。</li><li><strong>basal</strong> 洋葱。</li><li><strong>tewm</strong> 大蒜。</li><li><strong>tadam</strong> 番茄。</li><li><strong>karrotti</strong> 胡萝卜。</li><li><strong>ħass</strong> 生菜。</li><li><strong>ħjar</strong> 黄瓜。</li></ul><h3 id="第-5-题-肉店和鱼店" tabindex="-1">第 5 题：肉店和鱼店 <a class="header-anchor" href="#第-5-题-肉店和鱼店" aria-label="Permalink to &quot;第 5 题：肉店和鱼店&quot;">​</a></h3><p><strong>F’din il-kaxxa ikteb kemm tista’ tipi ta’ laħam li ssib mingħand tal-laħam, u tipi ta’ ħut li ssib mingħand tal-ħut.</strong></p><p>中文：列出肉店出售的肉类，以及鱼店出售的鱼类。</p><ul><li><strong>tipi</strong> 种类。</li><li><strong>ta’ laħam</strong> 肉的。</li><li><strong>li ssib</strong> 你找到的。</li><li><strong>mingħand tal-laħam</strong> 从肉店／肉贩那里。</li><li><strong>u</strong> 和。</li><li><strong>ta’ ħut</strong> 鱼的。</li><li><strong>mingħand tal-ħut</strong> 从鱼店／鱼贩那里。</li></ul><table><thead><tr><th>Tal-Laħam：肉类参考答案</th><th>Tal-Ħut：鱼类参考答案</th></tr></thead><tbody><tr><td><strong>tiġieġ</strong> 鸡肉<br><strong>ċanga</strong> 牛肉<br><strong>majjal</strong> 猪肉<br><strong>ħaruf</strong> 羊羔肉<br><strong>fenek</strong> 兔肉<br><strong>dundjan</strong> 火鸡肉</td><td><strong>tonn</strong> 金枪鱼<br><strong>salamun</strong> 三文鱼<br><strong>sardin</strong> 沙丁鱼<br><strong>lampuki</strong> 鲯鳅／当地常见的 lampuka 鱼（复数）<br><strong>awrat</strong> 金头鲷<br><strong>spnott</strong> 海鲈鱼</td></tr></tbody></table><p><strong>注意：</strong> <code>tal-laħam / tal-ħut / tal-ħaxix</code> 在日常语境可指经营这些商品的人或店家，不只是字面“肉的／鱼的／蔬菜的”。</p><hr><h2 id="_3-第-6-题-衣物清单" tabindex="-1">3 第 6 题：衣物清单 <a class="header-anchor" href="#_3-第-6-题-衣物清单" aria-label="Permalink to &quot;3 第 6 题：衣物清单&quot;">​</a></h2><p><strong>F’din il-kaxxa ikteb kemm tista’ tipi ta’ ħwejjeġ li ssib f’ħanut tal-ħwejjeġ.</strong></p><p>中文：在框中尽可能多写出服装店里的衣物种类。</p><ul><li><strong>f’din il-kaxxa</strong> 在这个框里。</li><li><strong>ikteb</strong> 写。</li><li><strong>kemm tista’</strong> 尽可能多。</li><li><strong>tipi ta’ ħwejjeġ</strong> 衣服种类。</li><li><strong>li ssib</strong> 你能找到的。</li><li><strong>f’ħanut</strong> 在商店里。</li><li><strong>tal-ħwejjeġ</strong> 卖衣服的。</li></ul><p>参考答案：</p><ul><li><strong>flokk</strong> 上衣、T 恤。</li><li><strong>qmis</strong> 衬衫。</li><li><strong>qalziet</strong> 裤子。</li><li><strong>ġins</strong> 牛仔裤。</li><li><strong>dublett</strong> 半身裙。</li><li><strong>libsa</strong> 连衣裙／套装，视语境而定。</li><li><strong>ġakketta</strong> 夹克、外套。</li><li><strong>kowt</strong> 大衣。</li><li><strong>kalzetti</strong> 袜子。</li><li><strong>żraben</strong> 鞋子。</li><li><strong>kappell</strong> 帽子。</li><li><strong>xalla</strong> 披肩。</li><li><strong>ċintorin</strong> 腰带。</li></ul><h3 id="口语任务一-穿什么" tabindex="-1">口语任务一：穿什么 <a class="header-anchor" href="#口语任务一-穿什么" aria-label="Permalink to &quot;口语任务一：穿什么&quot;">​</a></h3><p><strong>It-Taħdit — X’se tilbes biex tmur...? (Jien se nilbes...)</strong></p><ul><li><strong>it-taħdit</strong> 口语、说话。</li><li><strong>x’</strong> 什么。</li><li><strong>se</strong> 将要。</li><li><strong>tilbes</strong> 你穿。</li><li><strong>biex</strong> 为了。</li><li><strong>tmur</strong> 你去。</li><li><strong>jien</strong> 我。</li><li><strong>nilbes</strong> 我穿；区别于“你穿”tilbes。</li></ul><table><thead><tr><th>情景与参考回答</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Ix-xogħol? — Jien se nilbes qmis u qalziet għax-xogħol.</td><td>去上班？——我会穿衬衫和裤子上班。<br><strong>ix-xogħol</strong> 工作<br><strong>jien se nilbes</strong> 我将穿<br><strong>qmis</strong> 衬衫<br><strong>u</strong> 和<br><strong>qalziet</strong> 裤子<br><strong>għax-xogħol</strong> 去上班（għal + 冠词；不是“因为工作”）。</td></tr><tr><td>Il-baħar? — Jien se nilbes malja u sandli biex immur il-baħar.</td><td>去海边？——我会穿泳衣和凉鞋去海边。<br><strong>il-baħar</strong> 海／海边<br><strong>malja</strong> 泳衣<br><strong>sandli</strong> 凉鞋<br><strong>biex</strong> 为了<br><strong>immur</strong> 我去。</td></tr><tr><td>Xi tieġ jew okkażjoni speċjali? — Jien se nilbes libsa sabiħa għal tieġ.</td><td>去婚礼或特殊场合？——我会穿漂亮裙子参加婚礼。<br><strong>xi</strong> 某个<br><strong>tieġ</strong> 婚礼<br><strong>jew</strong> 或者<br><strong>okkażjoni speċjali</strong> 特殊场合<br><strong>libsa sabiħa</strong> 漂亮的裙子<br><strong>għal tieġ</strong> 为婚礼、参加婚礼。</td></tr><tr><td>Tiekol f’restorant? — Jien se nilbes qmis u ġakketta biex immur niekol f’restorant.</td><td>去餐厅吃饭？——我会穿衬衫和夹克去餐厅。<br><strong>tiekol</strong> 你吃<br><strong>f’restorant</strong> 在餐厅<br><strong>ġakketta</strong> 夹克<br><strong>biex immur</strong> 为了我去<br><strong>niekol</strong> 我吃。</td></tr></tbody></table><h3 id="口语任务二-买什么" tabindex="-1">口语任务二：买什么 <a class="header-anchor" href="#口语任务二-买什么" aria-label="Permalink to &quot;口语任务二：买什么&quot;">​</a></h3><p><strong>X’se tixtri mis-supermarket biex...? (Jien se nixtri...)</strong></p><ul><li><strong>x’se tixtri</strong> 你将买什么。</li><li><strong>mis-supermarket</strong> 从超市。</li><li><strong>biex</strong> 为了。</li><li><strong>jien se nixtri</strong> 我将购买。</li></ul><table><thead><tr><th>题目与参考回答</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Tipprepara xi ħaġa ħafifa għall-brejk tax-xogħol? — Jien se nixtri ħobż, ġobon u tadam biex nipprepara ftira.</td><td>准备工作休息时吃的简餐？——我会买面包、奶酪和番茄做 ftira。<br><strong>tipprepara</strong> 你准备<br><strong>xi ħaġa</strong> 某样东西<br><strong>ħafifa</strong> 轻便的、清淡的<br><strong>għall-brejk</strong> 用于休息时间<br><strong>tax-xogħol</strong> 工作的<br><strong>ħobż</strong> 面包<br><strong>ġobon</strong> 奶酪<br><strong>tadam</strong> 番茄<br><strong>biex nipprepara</strong> 为了我准备<br><strong>ftira</strong> 马耳他式面包／夹馅面包。</td></tr><tr><td>Issajjar l-ikla tal-Ħadd? — Jien se nixtri fenek, patata, basal u ħaxix biex insajjar stuffat tal-fenek.</td><td>做星期日午餐？——我会买兔肉、土豆、洋葱和蔬菜做炖兔肉。<br><strong>issajjar</strong> 你烹饪<br><strong>l-ikla</strong> 这一餐<br><strong>tal-Ħadd</strong> 星期日的<br><strong>fenek</strong> 兔子／兔肉<br><strong>patata</strong> 土豆<br><strong>basal</strong> 洋葱<br><strong>ħaxix</strong> 蔬菜<br><strong>biex insajjar</strong> 为了我烹饪<br><strong>stuffat</strong> 炖菜<br><strong>tal-fenek</strong> 兔肉的。</td></tr></tbody></table><p>第二个回答沿用教材已给的示例，不将其误列为原题空白。</p><hr><h2 id="_4-果蔬表补全与逐词解析" tabindex="-1">4 果蔬表补全与逐词解析 <a class="header-anchor" href="#_4-果蔬表补全与逐词解析" aria-label="Permalink to &quot;4 果蔬表补全与逐词解析&quot;">​</a></h2><p><strong>Il-frott u l-ħaxix</strong>：水果和蔬菜。</p><ul><li><strong>il-frott</strong> 水果（集合名词）。</li><li><strong>u</strong> 和。</li><li><strong>l-ħaxix</strong> 蔬菜（集合名词）。</li></ul><p>本页主要是词汇对照，每行一个词／短语，不必强行拆成句子。</p><table><thead><tr><th>原表词</th><th>马耳他语参考答案</th><th>中文与说明</th></tr></thead><tbody><tr><td>Cabbages</td><td><strong>kaboċċi</strong></td><td>卷心菜；原表已给。</td></tr><tr><td>Onions</td><td><strong>basal</strong></td><td>洋葱；集合名词。</td></tr><tr><td>Garlic</td><td><strong>tewm</strong></td><td>大蒜。</td></tr><tr><td>Potatoes</td><td><strong>patata</strong></td><td>土豆。</td></tr><tr><td>Cucumbers</td><td><strong>ħjar</strong></td><td>黄瓜；单个可说 ħjara。</td></tr><tr><td>Cauliflower</td><td><strong>pastard</strong></td><td>花椰菜、菜花。</td></tr><tr><td>Beans</td><td><strong>fażola</strong></td><td>菜豆／豆类；蚕豆另可说 ful，种类有别。</td></tr><tr><td>Pumpkins</td><td><strong>qargħa aħmar</strong></td><td>南瓜的常见表达。<br><strong>qargħa</strong> 瓜<br><strong>aħmar</strong> 红色；该食材名称作为固定组合记忆。</td></tr><tr><td>Peas</td><td><strong>piżelli</strong></td><td>豌豆。</td></tr><tr><td>Mushrooms</td><td><strong>faqqiegħ</strong></td><td>蘑菇、菌菇。</td></tr><tr><td>Carrots</td><td><strong>karrotti</strong></td><td>胡萝卜；单数 karrotta。</td></tr><tr><td>Lettuce</td><td><strong>ħass</strong></td><td>生菜。</td></tr><tr><td>Bell Peppers</td><td><strong>bżar ħelu</strong></td><td>甜椒。<br><strong>bżar</strong> 椒类<br><strong>ħelu</strong> 甜的；也常按颜色区分。</td></tr><tr><td>Spinich [原拼写]</td><td><strong>spinaċi</strong></td><td>菠菜；英文标准拼写 spinach。</td></tr><tr><td>Oranges</td><td><strong>larinġ</strong></td><td>橙子；原表已给，指集合。</td></tr><tr><td>Grapefruits</td><td><strong>grejpfrut</strong></td><td>葡萄柚；借词表达，地区或词典可有异体。</td></tr><tr><td>Lemons</td><td><strong>lumi</strong></td><td>柠檬；单个可说 lumija。</td></tr><tr><td>Apples</td><td><strong>tuffieħ</strong></td><td>苹果（集合）；单个 tuffieħa。</td></tr><tr><td>Banana</td><td><strong>banana</strong></td><td>一根香蕉；多根可说 banana 作为集合或用可数形式，须结合语境。</td></tr><tr><td>Pears</td><td><strong>lanġas</strong></td><td>梨（集合）；单个 lanġasa，可数复数 lanġasiet。</td></tr><tr><td>Grapes</td><td><strong>għeneb</strong></td><td>葡萄（集合）。</td></tr><tr><td>Watermelons</td><td><strong>dulliegħ</strong></td><td>西瓜（集合）；单个 dulliegħa。</td></tr><tr><td>Melons</td><td><strong>bettieħ</strong></td><td>甜瓜（集合）；单个 bettieħa。</td></tr><tr><td>Peaches</td><td><strong>ħawħ</strong></td><td>桃（集合）；单个 ħawħa。</td></tr><tr><td>Plums</td><td><strong>għanbaqar</strong></td><td>李子（集合）。</td></tr><tr><td>Strawberries</td><td><strong>frawli</strong></td><td>草莓（集合）。</td></tr><tr><td>Cherries</td><td><strong>ċirasa</strong></td><td>樱桃的常见集合表达；具体可数形式另依语境。</td></tr><tr><td>Tadam [原表已为马耳他语]</td><td><strong>tadam</strong>；英文 tomatoes</td><td>番茄（集合）；单个 tadama。不能把 Tadam 当成需译成马耳他语的英文。</td></tr></tbody></table><p><strong>学习重点：</strong> 果蔬常用集合名词；“一颗／一根”和“作为一类食材”不一定用同一词形。不要把所有集合名词简单当作英语式复数。</p><hr><h2 id="_5-配料说明逐句解析" tabindex="-1">5 配料说明逐句解析 <a class="header-anchor" href="#_5-配料说明逐句解析" aria-label="Permalink to &quot;5 配料说明逐句解析&quot;">​</a></h2><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Il-Qari – Aqra din ir-riċetta.</td><td>阅读：读这份食谱。<br><strong>il-qari</strong> 阅读<br><strong>aqra</strong> 读<br><strong>din</strong> 这份（阴性）<br><strong>ir-riċetta</strong> 食谱。</td></tr><tr><td>Ir-riċetta tal-lum hija r-riċetta tal-kejk tal-Oreo.</td><td>今天的食谱是 Oreo 蛋糕。<br><strong>ir-riċetta</strong> 食谱<br><strong>tal-lum</strong> 今天的<br><strong>hija</strong> 是（阴性）<br><strong>tal-kejk</strong> 蛋糕的<br><strong>tal-Oreo</strong> Oreo 的。</td></tr><tr><td>L-ingredjenti li għandkom bżonn huma...</td><td>你们需要的配料是……<br><strong>l-ingredjenti</strong> 配料（复数）<br><strong>li</strong> ……的<br><strong>għandkom bżonn</strong> 你们需要<br><strong>huma</strong> 是（复数）。</td></tr></tbody></table><h3 id="每项配料的词语与数量" tabindex="-1">每项配料的词语与数量 <a class="header-anchor" href="#每项配料的词语与数量" aria-label="Permalink to &quot;每项配料的词语与数量&quot;">​</a></h3><table><thead><tr><th>原文用量</th><th>数字的文字参考</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>200g dqiq</td><td>mitejn gramma dqiq</td><td>200 克面粉。<br><strong>mitejn</strong> 二百<br><strong>gramma</strong> 克<br><strong>dqiq</strong> 面粉。</td></tr><tr><td>280g zokkor</td><td>mitejn u tmenin gramma zokkor</td><td>280 克糖。<br><strong>mitejn</strong> 二百<br><strong>u</strong> 和<br><strong>tmenin</strong> 八十<br><strong>zokkor</strong> 糖。</td></tr><tr><td>40g trab taċ-ċikkulata</td><td>erbgħin gramma trab taċ-ċikkulata</td><td>40 克巧克力粉。<br><strong>erbgħin</strong> 四十<br><strong>trab</strong> 粉末<br><strong>taċ-ċikkulata</strong> 巧克力的；烘焙中按原材料名称理解，不擅改成另一个配料。</td></tr><tr><td>3 kuċċarini trab tal-ħami</td><td>tliet kuċċarini trab tal-ħami</td><td>三茶匙泡打粉。<br><strong>tliet</strong> 三（接名词）<br><strong>kuċċarini</strong> 茶匙（复数）<br><strong>trab</strong> 粉<br><strong>tal-ħami</strong> 烘焙用的。</td></tr><tr><td>Ftit melħ</td><td>ftit melħ</td><td>少许盐。<br><strong>ftit</strong> 一点<br><strong>melħ</strong> 盐。</td></tr><tr><td>80g butir mhux mielaħ</td><td>tmenin gramma butir mhux mielaħ</td><td>80 克无盐黄油。<br><strong>tmenin</strong> 八十<br><strong>butir</strong> 黄油<br><strong>mhux</strong> 不是、不<br><strong>mielaħ</strong> 咸的。</td></tr><tr><td>240ml ħalib</td><td>mitejn u erbgħin millilitru ħalib</td><td>240 毫升牛奶。<br><strong>mitejn</strong> 二百<br><strong>u erbgħin</strong> 加四十<br><strong>millilitru</strong> 毫升<br><strong>ħalib</strong> 牛奶。</td></tr><tr><td>3 bajdiet</td><td>tliet bajdiet</td><td>三个鸡蛋。<br><strong>tliet</strong> 三<br><strong>bajdiet</strong> 可数的鸡蛋（复数）；集合名词是 bajd。</td></tr><tr><td>½ kuċċarina essenza tal-vanilla</td><td>nofs kuċċarina essenza tal-vanilla</td><td>半茶匙香草精。<br><strong>nofs</strong> 一半<br><strong>kuċċarina</strong> 茶匙（单数）<br><strong>essenza</strong> 香精<br><strong>tal-vanilla</strong> 香草的。</td></tr><tr><td>12-il gallettina tal-Oreo</td><td>tnax-il gallettina tal-Oreo</td><td>十二块 Oreo 饼干。<br><strong>tnax-il</strong> 十二，接名词的形式<br><strong>gallettina</strong> 饼干（此结构用单数）<br><strong>tal-Oreo</strong> Oreo 品牌的。</td></tr></tbody></table><hr><h2 id="_6-题目解析" tabindex="-1">6 题目解析 <a class="header-anchor" href="#_6-题目解析" aria-label="Permalink to &quot;6 题目解析&quot;">​</a></h2><p><strong>Imla l-vojt bin-numri fi kliem, skont kif mitlub u skont l-ingredjenti li hemm fir-riċetta.</strong></p><p>中文：按要求和食谱配料，用文字写出数字，补全空格。</p><ul><li><strong>imla l-vojt</strong> 填空。</li><li><strong>bin-numri</strong> 用数字。</li><li><strong>fi kliem</strong> 用文字。</li><li><strong>skont</strong> 根据。</li><li><strong>kif mitlub</strong> 按所要求的方式。</li><li><strong>u</strong> 和。</li><li><strong>l-ingredjenti</strong> 配料。</li><li><strong>li hemm</strong> 存在的、列出的。</li><li><strong>fir-riċetta</strong> 在食谱中。</li></ul><h3 id="补全后的步骤与逐句分析" tabindex="-1">补全后的步骤与逐句分析 <a class="header-anchor" href="#补全后的步骤与逐句分析" aria-label="Permalink to &quot;补全后的步骤与逐句分析&quot;">​</a></h3><p><strong>Il-metodu — L-ewwel pass</strong>：制作方法——第一步。</p><ul><li><strong>il-metodu</strong> 方法。</li><li><strong>l-ewwel</strong> 第一。</li><li><strong>pass</strong> 步骤。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Ixgħel il-forn minn qabel fuq it-temperatura ta’ 170°C — mija u sebgħin grad Celsius.</td><td>提前将烤箱预热到 170 摄氏度。<br><strong>ixgħel</strong> 打开、点燃（命令式）<br><strong>il-forn</strong> 烤箱<br><strong>minn qabel</strong> 提前<br><strong>fuq</strong> 在……设定上<br><strong>it-temperatura</strong> 温度<br><strong>ta’</strong> 为……的<br><strong>mija u sebgħin</strong> 一百七十<br><strong>grad Celsius</strong> 摄氏度。</td></tr><tr><td>Itfa’ mitejn gramma dqiq, mitejn u tmenin gramma zokkor, erbgħin gramma trab taċ-ċikkulata, tliet kuċċarini trab tal-ħami, ftit melħ u tmenin gramma butir fi skutella kbira.</td><td>把 200 克面粉、280 克糖、40 克巧克力粉、三茶匙泡打粉、少许盐和 80 克黄油放入大碗。<br><strong>itfa’</strong> 放入、倒入<br><strong>mitejn gramma dqiq</strong> 200 克面粉<br><strong>mitejn u tmenin gramma zokkor</strong> 280 克糖<br><strong>erbgħin gramma</strong> 40 克<br><strong>trab taċ-ċikkulata</strong> 巧克力粉<br><strong>tliet kuċċarini</strong> 三茶匙<br><strong>trab tal-ħami</strong> 泡打粉<br><strong>ftit melħ</strong> 少许盐<br><strong>u</strong> 和<br><strong>tmenin gramma butir</strong> 80 克黄油<br><strong>fi skutella</strong> 在碗里<br><strong>kbira</strong> 大的（阴性）。</td></tr><tr><td>Ħawwad sakemm ikollok konsistenza tajba.</td><td>搅拌到合适的稠度。<br><strong>ħawwad</strong> 搅拌<br><strong>sakemm</strong> 直到<br><strong>ikollok</strong> 你得到／你有<br><strong>konsistenza</strong> 稠度、质地<br><strong>tajba</strong> 好的、合适的。</td></tr></tbody></table><p><strong>It-tieni pass</strong>：第二步。</p><ul><li><strong>it-tieni</strong> 第二。</li><li><strong>pass</strong> 步骤。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Ħawwad mitejn u erbgħin millilitru ħalib, tliet bajdiet u nofs kuċċarina essenza tal-vanilla flimkien ġewwa kontenitur.</td><td>在容器中混合 240 毫升牛奶、三个鸡蛋和半茶匙香草精。<br><strong>ħawwad</strong> 混合<br><strong>mitejn u erbgħin millilitru</strong> 240 毫升<br><strong>ħalib</strong> 牛奶<br><strong>tliet bajdiet</strong> 三个鸡蛋<br><strong>u</strong> 和<br><strong>nofs kuċċarina</strong> 半茶匙<br><strong>essenza tal-vanilla</strong> 香草精<br><strong>flimkien</strong> 一起<br><strong>ġewwa</strong> 在……里面<br><strong>kontenitur</strong> 容器。</td></tr><tr><td>Wara żid din it-taħlita bil-mod, fit-taħlita tad-dqiq u ħawwad sew. (Li tkun għamilt qabel).</td><td>然后将此混合液慢慢加入先前准备的面粉混合物，搅匀。括号为原文补充说明，独立成句不完整。<br><strong>wara</strong> 之后<br><strong>żid</strong> 添加<br><strong>din</strong> 这份<br><strong>it-taħlita</strong> 混合物<br><strong>bil-mod</strong> 慢慢地<br><strong>fit-taħlita</strong> 到混合物里<br><strong>tad-dqiq</strong> 面粉的<br><strong>u</strong> 并且<br><strong>ħawwad sew</strong> 充分搅拌<br><strong>li</strong> ……的<br><strong>tkun għamilt</strong> 你已经做好的<br><strong>qabel</strong> 之前。</td></tr><tr><td>Farrak tnax-il gallettina tal-Oreo ġewwa din it-taħlita u ħawwadha magħhom.</td><td>将十二块 Oreo 饼干弄碎放入混合物，并与其搅合。<br><strong>farrak</strong> 弄碎<br><strong>tnax-il</strong> 十二（接名词）<br><strong>gallettina tal-Oreo</strong> Oreo 饼干<br><strong>ġewwa din it-taħlita</strong> 在这份混合物中<br><strong>u</strong> 并且<br><strong>ħawwadha</strong> 搅拌它（-ha 指阴性 taħlita）<br><strong>magħhom</strong> 和它们一起。</td></tr></tbody></table><p><strong>It-tielet pass</strong>：第三步。</p><ul><li><strong>it-tielet</strong> 第三。</li><li><strong>pass</strong> 步骤。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Ifrex din it-taħlita f’kontenitur tond b’dijametru ta’ ħamsa u għoxrin ċentimetru li qabel tkun dlikt bil-butir sabiex tevita li jeħel dan il-kejk.</td><td>将混合物铺入直径 25 厘米的圆形容器；容器事先抹黄油，以防蛋糕粘住。<br><strong>ifrex</strong> 铺开、摊开<br><strong>din it-taħlita</strong> 这份混合物<br><strong>f’kontenitur</strong> 在容器中<br><strong>tond</strong> 圆的<br><strong>b’dijametru</strong> 有……直径<br><strong>ta’</strong> 为……的<br><strong>ħamsa u għoxrin</strong> 二十五<br><strong>ċentimetru</strong> 厘米<br><strong>li</strong> ……的<br><strong>qabel</strong> 事先<br><strong>tkun dlikt</strong> 你已涂抹<br><strong>bil-butir</strong> 用黄油<br><strong>sabiex</strong> 为了<br><strong>tevita</strong> 你避免<br><strong>li jeħel</strong> 它粘住<br><strong>dan il-kejk</strong> 这个蛋糕。</td></tr></tbody></table><p><strong>Ir-raba’ pass</strong>：第四步。</p><ul><li><strong>ir-raba’</strong> 第四；不要与基数 erba’ 混淆。</li><li><strong>pass</strong> 步骤。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Aħmi l-kejk tal-Oreo ġewwa l-forn għal madwar tletin minuta.</td><td>把 Oreo 蛋糕放进烤箱烤约三十分钟。<br><strong>aħmi</strong> 烘烤<br><strong>l-kejk tal-Oreo</strong> Oreo 蛋糕<br><strong>ġewwa l-forn</strong> 在烤箱里<br><strong>għal</strong> 持续……时间<br><strong>madwar</strong> 大约<br><strong>tletin</strong> 三十<br><strong>minuta</strong> 分钟（此计数结构用单数）。</td></tr><tr><td>Wara oħroġ il-kejk, aqsmu u kulu!</td><td>然后取出蛋糕，切开它并享用！<br><strong>wara</strong> 然后<br><strong>oħroġ</strong> 取出、拿出<br><strong>il-kejk</strong> 蛋糕<br><strong>aqsmu</strong> 把它分开／切开（aqsam + 宾语 -u）<br><strong>u</strong> 并且<br><strong>kulu</strong> 吃它（这里按宾语 -u 理解；不因 -u 就一律当“你们”）。</td></tr></tbody></table><hr><h2 id="_7-命令式说明逐句解析" tabindex="-1">7 命令式说明逐句解析 <a class="header-anchor" href="#_7-命令式说明逐句解析" aria-label="Permalink to &quot;7 命令式说明逐句解析&quot;">​</a></h2><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>L-Imperattiv – Il-Kmand</td><td>命令式——命令。<br><strong>l-imperattiv</strong> 命令式<br><strong>il-kmand</strong> 命令。</td></tr><tr><td>X’qed tinnota dwar il-verbi li huma mmarkati bil-grassett f’paġna ?</td><td>你注意到所指页面上加粗动词有什么特点？原题页码空缺，按上下文看食谱步骤。<br><strong>x’</strong> 什么<br><strong>qed</strong> 正在<br><strong>tinnota</strong> 你注意到<br><strong>dwar</strong> 关于<br><strong>il-verbi</strong> 动词<br><strong>li huma</strong> 它们是……的<br><strong>mmarkati</strong> 标记的<br><strong>bil-grassett</strong> 以粗体<br><strong>f’paġna</strong> 在某页。</td></tr><tr><td>Dan jintuża meta tikkmanda lil xi ħadd, jew titlob xi ħaġa lil xi ħadd.</td><td>向别人发出命令或请求某事时使用它。<br><strong>dan</strong> 这个（指命令式）<br><strong>jintuża</strong> 被使用<br><strong>meta</strong> 当……时<br><strong>tikkmanda</strong> 你命令<br><strong>lil xi ħadd</strong> 某个人（宾语）<br><strong>jew</strong> 或者<br><strong>titlob</strong> 你请求<br><strong>xi ħaġa</strong> 某件事<br><strong>lil xi ħadd</strong> 向某个人。</td></tr><tr><td>Ħares lejn dawn il-verbi fl-imperattiv u ikteb sentenza bihom.</td><td>看这些命令式动词，并用它们造句。<br><strong>ħares lejn</strong> 看向、查看<br><strong>dawn il-verbi</strong> 这些动词<br><strong>fl-imperattiv</strong> 以命令式<br><strong>u</strong> 并且<br><strong>ikteb</strong> 写<br><strong>sentenza</strong> 一个句子<br><strong>bihom</strong> 用它们。</td></tr></tbody></table><p>特点参考回答：<strong>Dawn il-verbi jagħtu kmand jew struzzjoni.</strong> 这些动词给出命令或指示。</p><ul><li><strong>dawn il-verbi</strong> 这些动词。</li><li><strong>jagħtu</strong> 它们给出。</li><li><strong>kmand</strong> 命令。</li><li><strong>jew</strong> 或者。</li><li><strong>struzzjoni</strong> 指示。</li></ul><h3 id="_1–21-全部造句参考答案" tabindex="-1">1–21 全部造句参考答案 <a class="header-anchor" href="#_1–21-全部造句参考答案" aria-label="Permalink to &quot;1–21 全部造句参考答案&quot;">​</a></h3><table><thead><tr><th>动词与参考句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Agħti — Agħti l-ktieb lil Marija.</td><td>把书给 Marija。<br><strong>agħti</strong> 给<br><strong>l-ktieb</strong> 这本书<br><strong>lil Marija</strong> 给 Marija。</td></tr><tr><td>2. Ilbes — Ilbes il-kowt.</td><td>穿上大衣。<br><strong>ilbes</strong> 穿上<br><strong>il-kowt</strong> 大衣。</td></tr><tr><td>3. Agħmel — Agħmel l-eżerċizzju.</td><td>做练习。<br><strong>agħmel</strong> 做<br><strong>l-eżerċizzju</strong> 练习。</td></tr><tr><td>4. Ersaq — Ersaq hawn.</td><td>到这里来。<br><strong>ersaq</strong> 靠近、过来<br><strong>hawn</strong> 这里。</td></tr><tr><td>5. Irkeb — Irkeb il-karozza tal-linja.</td><td>上公交车。<br><strong>irkeb</strong> 乘坐、登上<br><strong>il-karozza tal-linja</strong> 公交车。</td></tr><tr><td>6. Iftaħ — Iftaħ il-bieb.</td><td>打开门。<br><strong>iftaħ</strong> 打开<br><strong>il-bieb</strong> 门。</td></tr><tr><td>7. Agħlaq — Agħlaq it-tieqa.</td><td>关上窗。<br><strong>agħlaq</strong> 关闭<br><strong>it-tieqa</strong> 窗户。</td></tr><tr><td>8. Ieqaf — Ieqaf hawn.</td><td>在这里停下。<br><strong>ieqaf</strong> 停止、停下<br><strong>hawn</strong> 这里。</td></tr><tr><td>9. Kul — Kul it-tuffieħa.</td><td>吃这个苹果。<br><strong>kul</strong> 吃<br><strong>it-tuffieħa</strong> 这个苹果。</td></tr><tr><td>10. Aħsel — Aħsel idejk.</td><td>洗手。<br><strong>aħsel</strong> 洗<br><strong>idejk</strong> 你的双手（双数 + 所有格）。</td></tr><tr><td>11. Aqbad — Aqbad il-ballun.</td><td>接住球。<br><strong>aqbad</strong> 抓住、接住<br><strong>il-ballun</strong> 球。</td></tr><tr><td>12. Itfa’ — Itfa’ z-zokkor fl-iskutella.</td><td>把糖倒进碗里。<br><strong>itfa’</strong> 放入、倒入<br><strong>z-zokkor</strong> 糖<br><strong>fl-iskutella</strong> 在碗里／进入碗中。</td></tr><tr><td>13. Sajjar — Sajjar l-ikla.</td><td>做这顿饭。<br><strong>sajjar</strong> 烹饪<br><strong>l-ikla</strong> 这顿饭。</td></tr><tr><td>14. Qatta’ — Qatta’ l-basal.</td><td>切洋葱。<br><strong>qatta’</strong> 切碎<br><strong>l-basal</strong> 洋葱。</td></tr><tr><td>15. Aħmi — Aħmi l-kejk.</td><td>烤蛋糕。<br><strong>aħmi</strong> 烘烤<br><strong>l-kejk</strong> 蛋糕。</td></tr><tr><td>16. Ħawwad — Ħawwad it-taħlita.</td><td>搅拌混合物。<br><strong>ħawwad</strong> 搅拌<br><strong>it-taħlita</strong> 混合物。</td></tr><tr><td>17. Dawwar — Dawwar il-paġna.</td><td>翻页。<br><strong>dawwar</strong> 转动、翻转<br><strong>il-paġna</strong> 这一页。</td></tr><tr><td>18. Ħallas — Ħallas il-kont.</td><td>付账。<br><strong>ħallas</strong> 支付<br><strong>il-kont</strong> 账单。</td></tr><tr><td>19. Farfar — Farfar il-mejda.</td><td>掸去桌上的灰尘。<br><strong>farfar</strong> 掸灰<br><strong>il-mejda</strong> 桌子。</td></tr><tr><td>20. Ċapċap — Ċapċap għalihom.</td><td>为他们鼓掌。<br><strong>ċapċap</strong> 鼓掌<br><strong>għalihom</strong> 为他们。</td></tr><tr><td>21. Farfar — Farfar l-ixkaffa.</td><td>掸去架子上的灰。<br><strong>farfar</strong> 掸灰；原题重复此动词，另造一句<br><strong>l-ixkaffa</strong> 架子。</td></tr></tbody></table><hr><h2 id="_8-22–30-全部造句参考答案" tabindex="-1">8 22–30 全部造句参考答案 <a class="header-anchor" href="#_8-22–30-全部造句参考答案" aria-label="Permalink to &quot;8 22–30 全部造句参考答案&quot;">​</a></h2><table><thead><tr><th>动词与参考句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>22. Kompli — Kompli l-eżerċizzju.</td><td>继续做练习。<br><strong>kompli</strong> 继续、完成<br><strong>l-eżerċizzju</strong> 练习。</td></tr><tr><td>23. Irranġa — Irranġa l-kamra.</td><td>整理房间。<br><strong>irranġa</strong> 整理、安排、修理<br><strong>l-kamra</strong> 房间。</td></tr><tr><td>24. Irritorna — Irritorna l-ktieb.</td><td>归还这本书。<br><strong>irritorna</strong> 归还、返回<br><strong>l-ktieb</strong> 书。</td></tr><tr><td>25. Ipprova — Ipprova din il-libsa.</td><td>试穿这条裙子。<br><strong>ipprova</strong> 尝试、试穿<br><strong>din</strong> 这条<br><strong>il-libsa</strong> 裙子。</td></tr><tr><td>26. Ifforma — Ifforma sentenza.</td><td>组成一个句子。<br><strong>ifforma</strong> 形成、组成<br><strong>sentenza</strong> 句子。</td></tr><tr><td>27. Ipprintja — Ipprintja d-dokument.</td><td>打印文件。<br><strong>ipprintja</strong> 打印<br><strong>d-dokument</strong> 文件。</td></tr><tr><td>28. Ipparkja — Ipparkja l-karozza hawn.</td><td>把车停在这里。<br><strong>ipparkja</strong> 停车<br><strong>l-karozza</strong> 汽车<br><strong>hawn</strong> 这里。</td></tr><tr><td>29. Iffajlja — Iffajlja d-dokument.</td><td>将文件归档。<br><strong>iffajlja</strong> 归档、存档<br><strong>d-dokument</strong> 文件。</td></tr><tr><td>30. Ibbukkja — Ibbukkja mejda għal tnejn.</td><td>订一张两人桌。<br><strong>ibbukkja</strong> 预订<br><strong>mejda</strong> 桌子<br><strong>għal</strong> 为<br><strong>tnejn</strong> 两个人；此处独立使用完整数词。</td></tr></tbody></table><h3 id="语源说明逐句理解" tabindex="-1">语源说明逐句理解 <a class="header-anchor" href="#语源说明逐句理解" aria-label="Permalink to &quot;语源说明逐句理解&quot;">​</a></h3><table><thead><tr><th>原文</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Il-verbi kollha ta’ paġna 5 huma Semitiċi, jiġifieri ġejjin mill-Għarbi.</td><td>“第 5 页的所有动词都是闪米特语来源，也就是来自阿拉伯语。”这是教材原句；引用页码不对应本 PDF。<br><strong>il-verbi</strong> 动词<br><strong>kollha</strong> 全部<br><strong>ta’ paġna 5</strong> 第 5 页的<br><strong>huma</strong> 是<br><strong>Semitiċi</strong> 闪米特语系的<br><strong>jiġifieri</strong> 也就是说<br><strong>ġejjin</strong> 来自、源自（复数）<br><strong>mill-Għarbi</strong> 从阿拉伯语。</td></tr><tr><td>Il-verbi ta’ dil-paġna mhumiex Semitiċi, iżda huma Rumanzi (Taljani) u Ingliżi.</td><td>“本页的动词不是闪米特来源，而是罗曼语（意大利语）和英语来源。”属教学概括，不足以逐词判定词源。<br><strong>il-verbi</strong> 动词<br><strong>ta’ dil-paġna</strong> 这一页的<br><strong>mhumiex</strong> 它们不是<br><strong>Semitiċi</strong> 闪米特语系的<br><strong>iżda</strong> 但是、而是<br><strong>huma</strong> 它们是<br><strong>Rumanzi</strong> 罗曼语族的<br><strong>Taljani</strong> 意大利语的<br><strong>u</strong> 和<br><strong>Ingliżi</strong> 英语的。</td></tr><tr><td>Ikteb x’inhuma libsin dawn in-nies.</td><td>写出这些人穿着什么。<br><strong>ikteb</strong> 写<br><strong>x’inhuma</strong> 他们是什么／他们在……什么<br><strong>libsin</strong> 穿着（复数）<br><strong>dawn</strong> 这些<br><strong>in-nies</strong> 人。</td></tr></tbody></table><h3 id="女士照片-参考段落" tabindex="-1">女士照片：参考段落 <a class="header-anchor" href="#女士照片-参考段落" aria-label="Permalink to &quot;女士照片：参考段落&quot;">​</a></h3><blockquote><p>Il-mara liebsa flokk abjad, xorts tal-ġins u ġakketta bil-fjuri. Għandha nuċċali u ġiżirana twila.</p></blockquote><p>中文：这位女士穿着白色上衣、牛仔短裤和花卉图案外搭，戴着眼镜和一条长项链。衣物类别依据照片作一般描述，不推断品牌。</p><ul><li><strong>il-mara</strong> 这位女士。</li><li><strong>liebsa</strong> 穿着（阴性单数）。</li><li><strong>flokk</strong> 上衣。</li><li><strong>abjad</strong> 白色的。</li><li><strong>xorts</strong> 短裤。</li><li><strong>tal-ġins</strong> 牛仔材质的。</li><li><strong>u</strong> 和。</li><li><strong>ġakketta</strong> 夹克／外搭。</li><li><strong>bil-fjuri</strong> 带花卉图案的。</li><li><strong>għandha</strong> 她有、她戴着。</li><li><strong>nuċċali</strong> 眼镜。</li><li><strong>ġiżirana</strong> 项链。</li><li><strong>twila</strong> 长的（阴性）。</li></ul><hr><h2 id="_9-男士照片-参考段落" tabindex="-1">9 男士照片：参考段落 <a class="header-anchor" href="#_9-男士照片-参考段落" aria-label="Permalink to &quot;9 男士照片：参考段落&quot;">​</a></h2><blockquote><p>Ir-raġel liebes libsa skura, qmis ċara u ingravata. Għandu żarbun kannella.</p></blockquote><p>中文：这位男士穿深色西装、浅色衬衫，打着领带，穿棕色鞋。</p><ul><li><strong>ir-raġel</strong> 这位男士。</li><li><strong>liebes</strong> 穿着（阳性单数）。</li><li><strong>libsa</strong> 一套衣服，此处为西装。</li><li><strong>skura</strong> 深色的（配阴性 libsa）。</li><li><strong>qmis</strong> 衬衫。</li><li><strong>ċara</strong> 浅色的。</li><li><strong>u</strong> 和。</li><li><strong>ingravata</strong> 领带。</li><li><strong>għandu</strong> 他有／他穿着、戴着。</li><li><strong>żarbun</strong> 鞋、鞋类。</li><li><strong>kannella</strong> 棕色。</li></ul><h3 id="八人插图-题目与答案" tabindex="-1">八人插图：题目与答案 <a class="header-anchor" href="#八人插图-题目与答案" aria-label="Permalink to &quot;八人插图：题目与答案&quot;">​</a></h3><p><strong>X’inhuma lebsin? Ikteb in-numru fil-kaxxa t-tajba.</strong> 他们穿着什么？把编号写在正确的方框中。</p><ul><li><strong>x’inhuma lebsin</strong> 他们穿着什么；与上一页 libsin 均按材料形式识读。</li><li><strong>ikteb</strong> 写。</li><li><strong>in-numru</strong> 编号。</li><li><strong>fil-kaxxa</strong> 在方框里。</li><li><strong>t-tajba</strong> 正确的。</li></ul><p>插图从左至右填写：<strong>6、3、1、2、7、5、8、4</strong>。</p><table><thead><tr><th>人物原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Marija liebsa flokk biċ-ċingi vjola, ġins u żarbun tat-takkuna kannella. Għandha wkoll ċintorin kannella.</td><td>Marija 穿紫色吊带上衣、牛仔裤、棕色高跟鞋，另有棕色腰带。<br><strong>Marija</strong> 人名<br><strong>liebsa</strong> 穿着（女）<br><strong>flokk</strong> 上衣<br><strong>biċ-ċingi</strong> 带吊带的<br><strong>vjola</strong> 紫色<br><strong>ġins</strong> 牛仔裤<br><strong>u</strong> 和<br><strong>żarbun tat-takkuna</strong> 高跟鞋<br><strong>kannella</strong> 棕色<br><strong>għandha</strong> 她有／戴着<br><strong>wkoll</strong> 也<br><strong>ċintorin</strong> 腰带。</td></tr><tr><td>2. Toni liebes flokk bil-komma qasira aħmar, ġins, ċintorin iswed u żarbun kannella.</td><td>Toni 穿红色短袖上衣、牛仔裤、黑腰带和棕色鞋。<br><strong>Toni</strong> 人名<br><strong>liebes</strong> 穿着（男）<br><strong>flokk</strong> 上衣<br><strong>bil-komma</strong> 有袖子的<br><strong>qasira</strong> 短的（修饰 komma）<br><strong>aħmar</strong> 红色（修饰 flokk）<br><strong>ġins</strong> 牛仔裤<br><strong>ċintorin</strong> 腰带<br><strong>iswed</strong> 黑色<br><strong>u</strong> 和<br><strong>żarbun kannella</strong> 棕色鞋。</td></tr><tr><td>3. Lina liebsa flokk aħdar, qalziet griż u żarbun iswed.</td><td>Lina 穿绿色上衣、灰裤子和黑鞋。<br><strong>Lina</strong> 人名<br><strong>liebsa</strong> 穿着<br><strong>flokk aħdar</strong> 绿色上衣<br><strong>qalziet griż</strong> 灰裤子<br><strong>u</strong> 和<br><strong>żarbun iswed</strong> 黑色鞋。</td></tr><tr><td>4. Fredu liebes qalziet aħdar, qmis, ġakketta tal-ġins u żarbun iswed. Taħt il-qmis għandu flokk abjad.</td><td>Fredu 穿绿裤子、衬衫、牛仔夹克和黑鞋；衬衫下面还有白上衣。<br><strong>Fredu</strong> 人名<br><strong>liebes</strong> 穿着<br><strong>qalziet aħdar</strong> 绿裤子<br><strong>qmis</strong> 衬衫<br><strong>ġakketta tal-ġins</strong> 牛仔夹克<br><strong>u</strong> 和<br><strong>żarbun iswed</strong> 黑鞋<br><strong>taħt</strong> 在……下面<br><strong>il-qmis</strong> 衬衫<br><strong>għandu</strong> 他有／穿着<br><strong>flokk abjad</strong> 白上衣。</td></tr><tr><td>5. Luċija liebsa blaws griż, dublett blu ċar, tajz trasparenti, żarbun tat-takkuna kannella u ġiżirana.</td><td>Luċija 穿灰色女衬衣、浅蓝裙、透明连裤袜、棕色高跟鞋，并戴项链。<br><strong>Luċija</strong> 人名<br><strong>liebsa</strong> 穿着<br><strong>blaws</strong> 女式衬衣<br><strong>griż</strong> 灰色<br><strong>dublett</strong> 半身裙<br><strong>blu ċar</strong> 浅蓝色<br><strong>tajz</strong> 连裤袜<br><strong>trasparenti</strong> 透明的<br><strong>żarbun tat-takkuna</strong> 高跟鞋<br><strong>kannella</strong> 棕色<br><strong>u</strong> 和<br><strong>ġiżirana</strong> 项链。</td></tr><tr><td>6. Pawlu liebes flokk tal-komma qasira aħdar, ġins blu u żarbun kannella.</td><td>Pawlu 穿绿色短袖上衣、蓝色牛仔裤和棕色鞋。<br><strong>Pawlu</strong> 人名<br><strong>liebes</strong> 穿着<br><strong>flokk</strong> 上衣<br><strong>tal-komma qasira</strong> 短袖的<br><strong>aħdar</strong> 绿色<br><strong>ġins blu</strong> 蓝色牛仔裤<br><strong>u</strong> 和<br><strong>żarbun kannella</strong> 棕色鞋。</td></tr><tr><td>7. Kristina għandha flokk biċ-ċingi aħdar, qalziet blu u fuqu dublett roża. Liebsa wkoll buż blu.</td><td>Kristina 穿绿色吊带上衣、蓝裤子，裤子外面套粉红裙，另穿蓝靴。<br><strong>Kristina</strong> 人名<br><strong>għandha</strong> 她有／穿着<br><strong>flokk biċ-ċingi</strong> 吊带上衣<br><strong>aħdar</strong> 绿色<br><strong>qalziet blu</strong> 蓝裤子<br><strong>u</strong> 和<br><strong>fuqu</strong> 在它外面／上面（指裤子）<br><strong>dublett roża</strong> 粉红裙<br><strong>liebsa</strong> 穿着<br><strong>wkoll</strong> 也<br><strong>buż blu</strong> 蓝色靴子。</td></tr><tr><td>8. Rita liebsa flokk aħdar bil-komma qasira. Fuqu għandha flokk taċ-ċingi blu. Liebsa wkoll qalziet griż u żarbun iswed.</td><td>Rita 内穿绿色短袖上衣，外穿蓝色吊带上衣，另穿灰裤子和黑鞋。<br><strong>Rita</strong> 人名<br><strong>liebsa</strong> 穿着<br><strong>flokk aħdar</strong> 绿色上衣<br><strong>bil-komma qasira</strong> 短袖的<br><strong>fuqu</strong> 在它上面／外面<br><strong>għandha</strong> 她有／穿着<br><strong>flokk taċ-ċingi blu</strong> 蓝色吊带上衣<br><strong>wkoll</strong> 也<br><strong>qalziet griż</strong> 灰裤子<br><strong>u</strong> 和<br><strong>żarbun iswed</strong> 黑鞋。</td></tr></tbody></table><p>图片来源文字 <strong>Il-Malti bħala lingwa barranija</strong>：马耳他语作为外语。</p><ul><li><strong>il-Malti</strong> 马耳他语。</li><li><strong>bħala</strong> 作为。</li><li><strong>lingwa</strong> 语言。</li><li><strong>barranija</strong> 外国的（阴性）。</li><li><strong>Stephanie Dempsey</strong> 原图作者署名。</li></ul><hr><h2 id="_10-a-1–20-的读法" tabindex="-1">10 A. 1–20 的读法 <a class="header-anchor" href="#_10-a-1–20-的读法" aria-label="Permalink to &quot;10 A. 1–20 的读法&quot;">​</a></h2><p><strong>In-numri bil-Malti</strong>：马耳他语数字。</p><ul><li><strong>in-numri</strong> 数字。</li><li><strong>bil-Malti</strong> 用马耳他语。</li></ul><table><thead><tr><th>数字</th><th>马耳他语与中文</th><th>数字</th><th>马耳他语与中文</th></tr></thead><tbody><tr><td>1</td><td><strong>wieħed</strong> 一（独立／阳性）</td><td>11</td><td><strong>ħdax</strong> 十一</td></tr><tr><td>2</td><td><strong>tnejn</strong> 二</td><td>12</td><td><strong>tnax</strong> 十二</td></tr><tr><td>3</td><td><strong>tlieta</strong> 三</td><td>13</td><td><strong>tlettax</strong> 十三</td></tr><tr><td>4</td><td><strong>erbgħa</strong> 四</td><td>14</td><td><strong>erbatax</strong> 十四</td></tr><tr><td>5</td><td><strong>ħamsa</strong> 五</td><td>15</td><td><strong>ħmistax</strong> 十五</td></tr><tr><td>6</td><td><strong>sitta</strong> 六</td><td>16</td><td><strong>sittax</strong> 十六</td></tr><tr><td>7</td><td><strong>sebgħa</strong> 七</td><td>17</td><td><strong>sbatax</strong> 十七</td></tr><tr><td>8</td><td><strong>tmienja</strong> 八</td><td>18</td><td><strong>tmintax</strong> 十八</td></tr><tr><td>9</td><td><strong>disgħa</strong> 九</td><td>19</td><td><strong>dsatax</strong> 十九</td></tr><tr><td>10</td><td><strong>għaxra</strong> 十</td><td>20</td><td><strong>għoxrin</strong> 二十</td></tr></tbody></table><p>这些是独立读数形式；不能把 <code>erbgħa</code> 在所有位置都写成 <code>erba’</code>，后者是接名词时的形式。</p><h3 id="b-数字宾果听力" tabindex="-1">B. 数字宾果听力 <a class="header-anchor" href="#b-数字宾果听力" aria-label="Permalink to &quot;B. 数字宾果听力&quot;">​</a></h3><p><strong>Ejjew nilagħbu ftit tombla! Immarka n-numru li tisma’.</strong></p><p>中文：我们来玩一会儿数字宾果！标出你听到的数字。</p><ul><li><strong>ejjew</strong> 来吧（对多人）。</li><li><strong>nilagħbu</strong> 我们玩。</li><li><strong>ftit</strong> 一会儿、少量。</li><li><strong>tombla</strong> 宾果／数字抽签游戏。</li><li><strong>immarka</strong> 标记。</li><li><strong>n-numru</strong> 这个数字。</li><li><strong>li tisma’</strong> 你听到的。</li></ul><p><strong>答案状态：缺录音，不能确定应标哪几格。</strong> 空格是宾果布局的一部分，不是需要补数字的作业空白。</p><h3 id="c-电话号码" tabindex="-1">C. 电话号码 <a class="header-anchor" href="#c-电话号码" aria-label="Permalink to &quot;C. 电话号码&quot;">​</a></h3><p><strong>Ikteb in-numri ta’ dawn in-nies.</strong> 写出这些人的电话号码。</p><ul><li><strong>ikteb</strong> 写。</li><li><strong>in-numri</strong> 数字／电话号码。</li><li><strong>ta’</strong> ……的。</li><li><strong>dawn in-nies</strong> 这些人。</li><li><strong>is-Sur</strong> 先生。</li><li><strong>Vella</strong> 姓氏。</li></ul><p><strong>Is-Sur Vella — 21678723</strong> 的逐位参考读法：</p><blockquote><p>tnejn, wieħed, sitta, sebgħa, tmienja, sebgħa, tnejn, tlieta</p></blockquote><ul><li><strong>tnejn</strong> 2。</li><li><strong>wieħed</strong> 1。</li><li><strong>sitta</strong> 6。</li><li><strong>sebgħa</strong> 7。</li><li><strong>tmienja</strong> 8。</li><li><strong>sebgħa</strong> 7。</li><li><strong>tnejn</strong> 2。</li><li><strong>tlieta</strong> 3。</li></ul><p>电话按位读数是一种适合本题的读法，不把整个八位电话号码当成千万位的整数朗读。</p><hr><h2 id="_11-c-电话号码续题" tabindex="-1">11 C. 电话号码续题 <a class="header-anchor" href="#_11-c-电话号码续题" aria-label="Permalink to &quot;11 C. 电话号码续题&quot;">​</a></h2><table><thead><tr><th>原号码</th><th>逐位文字参考答案</th></tr></thead><tbody><tr><td>Is-Sur Dimech — 99871803</td><td><strong>disgħa</strong> 9<br><strong>disgħa</strong> 9<br><strong>tmienja</strong> 8<br><strong>sebgħa</strong> 7<br><strong>wieħed</strong> 1<br><strong>tmienja</strong> 8<br><strong>żero</strong> 0<br><strong>tlieta</strong> 3</td></tr><tr><td>Is-Sur Psaila — 27231234</td><td><strong>tnejn</strong> 2<br><strong>sebgħa</strong> 7<br><strong>tnejn</strong> 2<br><strong>tlieta</strong> 3<br><strong>wieħed</strong> 1<br><strong>tnejn</strong> 2<br><strong>tlieta</strong> 3<br><strong>erbgħa</strong> 4</td></tr><tr><td>Is-Sur Bonanno — 77002517</td><td><strong>sebgħa</strong> 7<br><strong>sebgħa</strong> 7<br><strong>żero</strong> 0<br><strong>żero</strong> 0<br><strong>tnejn</strong> 2<br><strong>ħamsa</strong> 5<br><strong>wieħed</strong> 1<br><strong>sebgħa</strong> 7</td></tr></tbody></table><p><strong>Dimech / Psaila / Bonanno</strong> 均为姓氏，称谓 <code>Is-Sur</code> 表示先生。</p><h3 id="d-算式" tabindex="-1">D. 算式 <a class="header-anchor" href="#d-算式" aria-label="Permalink to &quot;D. 算式&quot;">​</a></h3><p><strong>Aħdem dawn is-somom u ikteb it-tweġiba fi kliem bil-Malti.</strong></p><p>中文：完成这些算式，并用马耳他语文字写出答案。</p><ul><li><strong>aħdem</strong> 做、算。</li><li><strong>dawn</strong> 这些。</li><li><strong>is-somom</strong> 算式、计算题。</li><li><strong>u</strong> 并且。</li><li><strong>ikteb</strong> 写。</li><li><strong>it-tweġiba</strong> 答案。</li><li><strong>fi kliem</strong> 用文字。</li><li><strong>bil-Malti</strong> 用马耳他语。</li></ul><table><thead><tr><th>算式</th><th>数字答案</th><th>文字答案与中文</th></tr></thead><tbody><tr><td>1 + 5</td><td>6</td><td><strong>sitta</strong> 六；教材已给</td></tr><tr><td>7 − 3</td><td>4</td><td><strong>erbgħa</strong> 四</td></tr><tr><td>2 − 1</td><td>1</td><td><strong>wieħed</strong> 一</td></tr><tr><td>3 × 3</td><td>9</td><td><strong>disgħa</strong> 九</td></tr><tr><td>9 + 1</td><td>10</td><td><strong>għaxra</strong> 十</td></tr><tr><td>4 − 2</td><td>2</td><td><strong>tnejn</strong> 二</td></tr><tr><td>8 × 2</td><td>16</td><td><strong>sittax</strong> 十六</td></tr><tr><td>10 × 2</td><td>20</td><td><strong>għoxrin</strong> 二十</td></tr><tr><td>9 + 4</td><td>13</td><td><strong>tlettax</strong> 十三</td></tr><tr><td>10 + 7</td><td>17</td><td><strong>sbatax</strong> 十七</td></tr><tr><td>20 − 1</td><td>19</td><td><strong>dsatax</strong> 十九</td></tr><tr><td>7 × 2</td><td>14</td><td><strong>erbatax</strong> 十四</td></tr></tbody></table><p>这里答案独立使用，因此写 <code>erbgħa</code>，而不是名词前形式 <code>erba’</code>。</p><hr><h2 id="_12-复合数字结构" tabindex="-1">12 复合数字结构 <a class="header-anchor" href="#_12-复合数字结构" aria-label="Permalink to &quot;12 复合数字结构&quot;">​</a></h2><p><strong>In-Numri mill-20 sal-100 — Kompli din it-tabella.</strong> 从二十到一百的数字——补全表格。</p><ul><li><strong>in-numri</strong> 数字。</li><li><strong>mill-20</strong> 从 20。</li><li><strong>sal-100</strong> 到 100。</li><li><strong>kompli</strong> 补全。</li><li><strong>din it-tabella</strong> 这张表。</li></ul><p>21–99 中非整十的数字，本页采用 <strong>个位 + u + 整十</strong>：</p><ul><li><strong>wieħed</strong> 一。</li><li><strong>u</strong> 和、加。</li><li><strong>għoxrin</strong> 二十。</li><li><strong>wieħed u għoxrin</strong> 21。</li><li><strong>sebgħa u sittin</strong> 67，即 7 + 60。</li><li><strong>tnejn u erbgħin</strong> 42，即 2 + 40。</li></ul><h3 id="全表参考答案" tabindex="-1">全表参考答案 <a class="header-anchor" href="#全表参考答案" aria-label="Permalink to &quot;全表参考答案&quot;">​</a></h3><table><thead><tr><th>整十／百</th><th>中列：答案与拆解</th><th>右列：答案与拆解</th></tr></thead><tbody><tr><td><strong>għoxrin</strong> 20</td><td>21 = <strong>wieħed u għoxrin</strong><br><strong>wieħed</strong> 1<br><strong>u</strong> 和<br><strong>għoxrin</strong> 20</td><td>25 = <strong>ħamsa u għoxrin</strong><br><strong>ħamsa</strong> 5<br><strong>u</strong> 和<br><strong>għoxrin</strong> 20</td></tr><tr><td><strong>tletin</strong> 30</td><td>38 = <strong>tmienja u tletin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> 和<br><strong>tletin</strong> 30</td><td>33 = <strong>tlieta u tletin</strong><br><strong>tlieta</strong> 3<br><strong>u</strong> 和<br><strong>tletin</strong> 30</td></tr><tr><td><strong>erbgħin</strong> 40</td><td>42 = <strong>tnejn u erbgħin</strong><br><strong>tnejn</strong> 2<br><strong>u</strong> 和<br><strong>erbgħin</strong> 40</td><td>46 = <strong>sitta u erbgħin</strong><br><strong>sitta</strong> 6<br><strong>u</strong> 和<br><strong>erbgħin</strong> 40</td></tr><tr><td><strong>ħamsin</strong> 50</td><td>53 = <strong>tlieta u ħamsin</strong><br><strong>tlieta</strong> 3<br><strong>u</strong> 和<br><strong>ħamsin</strong> 50</td><td>59 = <strong>disgħa u ħamsin</strong><br><strong>disgħa</strong> 9<br><strong>u</strong> 和<br><strong>ħamsin</strong> 50</td></tr><tr><td><strong>sittin</strong> 60</td><td>64 = <strong>erbgħa u sittin</strong><br><strong>erbgħa</strong> 4<br><strong>u</strong> 和<br><strong>sittin</strong> 60</td><td>67 = <strong>sebgħa u sittin</strong><br><strong>sebgħa</strong> 7<br><strong>u</strong> 和<br><strong>sittin</strong> 60</td></tr><tr><td><strong>sebgħin</strong> 70</td><td>71 = <strong>wieħed u sebgħin</strong><br><strong>wieħed</strong> 1<br><strong>u</strong> 和<br><strong>sebgħin</strong> 70</td><td>78 = <strong>tmienja u sebgħin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> 和<br><strong>sebgħin</strong> 70</td></tr><tr><td><strong>tmenin</strong> 80</td><td>85 = <strong>ħamsa u tmenin</strong><br><strong>ħamsa</strong> 5<br><strong>u</strong> 和<br><strong>tmenin</strong> 80</td><td>88 = <strong>tmienja u tmenin</strong><br><strong>tmienja</strong> 8<br><strong>u</strong> 和<br><strong>tmenin</strong> 80</td></tr><tr><td><strong>disgħin</strong> 90</td><td>92 = <strong>tnejn u disgħin</strong><br><strong>tnejn</strong> 2<br><strong>u</strong> 和<br><strong>disgħin</strong> 90</td><td>96 = <strong>sitta u disgħin</strong><br><strong>sitta</strong> 6<br><strong>u</strong> 和<br><strong>disgħin</strong> 90</td></tr><tr><td><strong>mija</strong> 100</td><td>101 = <strong>mija u wieħed</strong><br><strong>mija</strong> 100<br><strong>u</strong> 和<br><strong>wieħed</strong> 1</td><td>105 = <strong>mija u ħamsa</strong><br><strong>mija</strong> 100<br><strong>u</strong> 和<br><strong>ħamsa</strong> 5</td></tr></tbody></table><p><strong>注意：</strong> 数字 <code>100</code> 独立读 <code>mija</code>；名词前常见 <code>mitt</code>，见下一页 <code>mitt ewro</code>，不照搬成 <code>mija ewro</code>。</p><hr><h2 id="_13-b-听力选项全部读法" tabindex="-1">13 B. 听力选项全部读法 <a class="header-anchor" href="#_13-b-听力选项全部读法" aria-label="Permalink to &quot;13 B. 听力选项全部读法&quot;">​</a></h2><p><strong>Agħmel ċirku madwar in-numru li tisma’.</strong> 圈出你听到的数字。</p><ul><li><strong>agħmel</strong> 做、画。</li><li><strong>ċirku</strong> 圆圈。</li><li><strong>madwar</strong> 围绕。</li><li><strong>in-numru</strong> 这个数字。</li><li><strong>li tisma’</strong> 你听到的。</li></ul><table><thead><tr><th>题号</th><th>左选项</th><th>右选项</th></tr></thead><tbody><tr><td>1</td><td>13 — <strong>tlettax</strong> 十三</td><td>33 — <strong>tlieta u tletin</strong> 三十三</td></tr><tr><td>2</td><td>51 — <strong>wieħed u ħamsin</strong> 五十一</td><td>59 — <strong>disgħa u ħamsin</strong> 五十九</td></tr><tr><td>3</td><td>60 — <strong>sittin</strong> 六十</td><td>65 — <strong>ħamsa u sittin</strong> 六十五</td></tr><tr><td>4</td><td>82 — <strong>tnejn u tmenin</strong> 八十二</td><td>28 — <strong>tmienja u għoxrin</strong> 二十八</td></tr><tr><td>5</td><td>75 — <strong>ħamsa u sebgħin</strong> 七十五</td><td>57 — <strong>sebgħa u ħamsin</strong> 五十七</td></tr><tr><td>6</td><td>49 — <strong>disgħa u erbgħin</strong> 四十九</td><td>94 — <strong>erbgħa u disgħin</strong> 九十四</td></tr><tr><td>7</td><td>22 — <strong>tnejn u għoxrin</strong> 二十二</td><td>23 — <strong>tlieta u għoxrin</strong> 二十三</td></tr><tr><td>8</td><td>9 — <strong>disgħa</strong> 九</td><td>99 — <strong>disgħa u disgħin</strong> 九十九</td></tr><tr><td>9</td><td>67 — <strong>sebgħa u sittin</strong> 六十七</td><td>76 — <strong>sitta u sebgħin</strong> 七十六</td></tr><tr><td>10</td><td>88 — <strong>tmienja u tmenin</strong> 八十八</td><td>82 — <strong>tnejn u tmenin</strong> 八十二</td></tr></tbody></table><p>复合数内部的 <strong>u</strong> 为“和”；前后各部分的数字义见第 11、13 页。<strong>缺录音，所有选项均保留，不假定正确选项。</strong></p><h3 id="c-数字填空-完整句子与逐词解析" tabindex="-1">C. 数字填空：完整句子与逐词解析 <a class="header-anchor" href="#c-数字填空-完整句子与逐词解析" aria-label="Permalink to &quot;C. 数字填空：完整句子与逐词解析&quot;">​</a></h3><p><strong>Imla l-vojt billi tikteb in-numri fi kliem — HW.</strong> 用文字写出数字填空——家庭作业。</p><ul><li><strong>imla l-vojt</strong> 填空。</li><li><strong>billi tikteb</strong> 通过写出。</li><li><strong>in-numri</strong> 数字。</li><li><strong>fi kliem</strong> 用文字。</li><li><strong>HW</strong> homework，家庭作业。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. In-nanna għandha tmenin sena u n-nannu għandu ħamsa u tmenin sena.</td><td>奶奶 80 岁，爷爷 85 岁。<br><strong>in-nanna</strong> 奶奶／外婆<br><strong>għandha</strong> 她有（年龄结构）<br><strong>tmenin</strong> 80<br><strong>sena</strong> 年<br><strong>u</strong> 和<br><strong>n-nannu</strong> 爷爷／外公<br><strong>għandu</strong> 他有<br><strong>ħamsa u tmenin</strong> 85<br><strong>sena</strong> 年。</td></tr><tr><td>2. Xtrajt tnejn u ħamsin ktieb biex naqra wieħed kull ġimgħa.</td><td>我买了 52 本书，打算每周读一本。<br><strong>xtrajt</strong> 我买了<br><strong>tnejn u ħamsin</strong> 52<br><strong>ktieb</strong> 书（此计数结构用单数）<br><strong>biex</strong> 为了<br><strong>naqra</strong> 我读<br><strong>wieħed</strong> 一本、一个（代指阳性 ktieb）<br><strong>kull</strong> 每<br><strong>ġimgħa</strong> 周。</td></tr><tr><td>3. Għandi ħamsa u għoxrin libsa; wieħed u tletin xalla u ħamsa u ħamsin kowt.</td><td>我有 25 条裙子、31 条披肩和 55 件大衣。<br><strong>għandi</strong> 我有<br><strong>ħamsa u għoxrin</strong> 25<br><strong>libsa</strong> 裙子／套装<br><strong>wieħed u tletin</strong> 31<br><strong>xalla</strong> 披肩<br><strong>u</strong> 和<br><strong>ħamsa u ħamsin</strong> 55<br><strong>kowt</strong> 大衣。</td></tr><tr><td>4. Infaqna sebgħa u sittin ewro biex irranġajna t-televixin.</td><td>我们花了 67 欧元修电视。<br><strong>infaqna</strong> 我们花费了<br><strong>sebgħa u sittin</strong> 67<br><strong>ewro</strong> 欧元<br><strong>biex</strong> 为了<br><strong>irranġajna</strong> 我们修好了（按原题过去式保留）<br><strong>t-televixin</strong> 电视。</td></tr><tr><td>5. Qlajt mitt ewro bħala rigal.</td><td>我收到了 100 欧元作为礼物。<br><strong>qlajt</strong> 我获得、收到<br><strong>mitt</strong> 一百（接名词）<br><strong>ewro</strong> 欧元<br><strong>bħala</strong> 作为<br><strong>rigal</strong> 礼物。</td></tr><tr><td>6a. Ommi żżewġet ta’ tmienja u għoxrin sena.</td><td>我母亲 28 岁结婚。<br><strong>ommi</strong> 我的母亲<br><strong>żżewġet</strong> 她结婚了<br><strong>ta’</strong> 在……年龄<br><strong>tmienja u għoxrin</strong> 28<br><strong>sena</strong> 年。</td></tr><tr><td>6b. Meta kellha disgħa u għoxrin sena, welldet lil oħti u meta kellha tnejn u tletin sena welldet lili.</td><td>她 29 岁生了我姐姐，32 岁生了我。<br><strong>meta</strong> 当……时<br><strong>kellha</strong> 她有（过去时，指年龄）<br><strong>disgħa u għoxrin</strong> 29<br><strong>sena</strong> 年<br><strong>welldet</strong> 她生下了<br><strong>lil oħti</strong> 我的姐姐（宾语）<br><strong>u</strong> 和<br><strong>tnejn u tletin</strong> 32<br><strong>lili</strong> 我（宾语）。</td></tr><tr><td>7. Morna l-Akkwarju Nazzjonali u rajna tnejn u sebgħin speċi ta’ ħut differenti.</td><td>我们去了国家水族馆，看见 72 种不同的鱼。<br><strong>morna</strong> 我们去了<br><strong>l-Akkwarju Nazzjonali</strong> 国家水族馆<br><strong>u</strong> 并且<br><strong>rajna</strong> 我们看见了<br><strong>tnejn u sebgħin</strong> 72<br><strong>speċi</strong> 种、物种<br><strong>ta’ ħut</strong> 鱼的<br><strong>differenti</strong> 不同的。</td></tr></tbody></table><p>第 4 题原文 <code>biex irranġajna</code> 的时态搭配不宜机械照搬到新句；作为学习改写可说 <strong>Infaqna sebgħa u sittin ewro fuq it-tiswija tat-televixin.</strong>（我们花 67 欧元修电视。）</p><ul><li><strong>fuq</strong> 用于、在……方面。</li><li><strong>it-tiswija</strong> 修理。</li><li><strong>tat-televixin</strong> 电视的。</li></ul><hr><h2 id="_14-语法说明逐句解析" tabindex="-1">14 语法说明逐句解析 <a class="header-anchor" href="#_14-语法说明逐句解析" aria-label="Permalink to &quot;14 语法说明逐句解析&quot;">​</a></h2><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>In-numri u n-nomi</td><td>数字与名词。<br><strong>in-numri</strong> 数字<br><strong>u</strong> 和<br><strong>n-nomi</strong> 名词。</td></tr><tr><td>In-nomi huma kliem li juru oġġetti, persuni, annimali u postijiet.</td><td>名词是表示物品、人物、动物和地点的词。<br><strong>in-nomi</strong> 名词<br><strong>huma</strong> 是<br><strong>kliem</strong> 词语<br><strong>li</strong> ……的<br><strong>juru</strong> 表示、显示<br><strong>oġġetti</strong> 物品<br><strong>persuni</strong> 人<br><strong>annimali</strong> 动物<br><strong>u</strong> 和<br><strong>postijiet</strong> 地点。</td></tr><tr><td>Meta n-numri jintużaw flimkien man-nomi, jistgħu jibdlu s-sura tagħhom.</td><td>数词和名词一起用时，数词可能改变形式。<br><strong>meta</strong> 当……时<br><strong>n-numri</strong> 数词<br><strong>jintużaw</strong> 被使用（复数）<br><strong>flimkien</strong> 一起<br><strong>man-nomi</strong> 与名词<br><strong>jistgħu</strong> 它们能够<br><strong>jibdlu</strong> 改变<br><strong>s-sura</strong> 形式<br><strong>tagħhom</strong> 它们的。</td></tr></tbody></table><h3 id="_1-置于名词后-区分性别" tabindex="-1">1：置于名词后，区分性别 <a class="header-anchor" href="#_1-置于名词后-区分性别" aria-label="Permalink to &quot;1：置于名词后，区分性别&quot;">​</a></h3><ul><li><strong>lapes wieħed</strong> 一支铅笔。</li><li><strong>lapes</strong> 铅笔，阳性。</li><li><strong>wieħed</strong> 一（阳性）。</li><li><strong>karta waħda</strong> 一张纸。</li><li><strong>karta</strong> 纸，阴性。</li><li><strong>waħda</strong> 一（阴性）。</li><li><strong>tifel wieħed</strong> 一个男孩。</li><li><strong>tifla waħda</strong> 一个女孩。</li><li><strong>m</strong> masculine，阳性。</li><li><strong>f</strong> feminine，阴性。</li></ul><h3 id="_2–10-数词变短-后接复数" tabindex="-1">2–10：数词变短，后接复数 <a class="header-anchor" href="#_2–10-数词变短-后接复数" aria-label="Permalink to &quot;2–10：数词变短，后接复数&quot;">​</a></h3><table><thead><tr><th>独立数字</th><th>名词前形式</th><th>普通复数例句与拆解</th><th>元音开头例句与拆解</th></tr></thead><tbody><tr><td><strong>tnejn</strong> 二</td><td><strong>żewġ / żewġt</strong></td><td><strong>żewġ lapsijiet</strong> 两支铅笔<br><strong>żewġ</strong> 两<br><strong>lapsijiet</strong> 铅笔（复数）</td><td><strong>żewġt itfal</strong> 两个孩子<br><strong>żewġt</strong> 两，接 itfal<br><strong>itfal</strong> 孩子（复数）</td></tr><tr><td><strong>tlieta</strong> 三</td><td><strong>tliet / tlitt</strong></td><td><strong>tliet karti</strong> 三张纸<br><strong>tliet</strong> 三<br><strong>karti</strong> 纸（复数）</td><td><strong>tlitt itfal</strong> 三个孩子<br><strong>tlitt</strong> 三<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>erbgħa</strong> 四</td><td><strong>erba’ / erbat</strong></td><td><strong>erba’ lapsijiet</strong> 四支铅笔<br><strong>erba’</strong> 四<br><strong>lapsijiet</strong> 铅笔</td><td><strong>erbat itfal</strong> 四个孩子<br><strong>erbat</strong> 四<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>ħamsa</strong> 五</td><td><strong>ħames / ħamest</strong></td><td><strong>ħames karti</strong> 五张纸<br><strong>ħames</strong> 五<br><strong>karti</strong> 纸</td><td><strong>ħamest itfal</strong> 五个孩子<br><strong>ħamest</strong> 五<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>sitta</strong> 六</td><td><strong>sitt</strong></td><td><strong>sitt lapsijiet</strong> 六支铅笔<br><strong>sitt</strong> 六<br><strong>lapsijiet</strong> 铅笔</td><td><strong>sitt itfal</strong> 六个孩子<br><strong>sitt</strong> 六<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>sebgħa</strong> 七</td><td><strong>seba’ / sebat</strong></td><td><strong>seba’ karti</strong> 七张纸<br><strong>seba’</strong> 七<br><strong>karti</strong> 纸</td><td><strong>sebat itfal</strong> 七个孩子<br><strong>sebat</strong> 七<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>tmienja</strong> 八</td><td><strong>tmien / tmint</strong></td><td><strong>tmien lapsijiet</strong> 八支铅笔<br><strong>tmien</strong> 八<br><strong>lapsijiet</strong> 铅笔</td><td><strong>tmint itfal</strong> 八个孩子<br><strong>tmint</strong> 八<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>disgħa</strong> 九</td><td><strong>disa’ / disat</strong></td><td><strong>disa’ karti</strong> 九张纸<br><strong>disa’</strong> 九<br><strong>karti</strong> 纸</td><td><strong>disat itfal</strong> 九个孩子<br><strong>disat</strong> 九<br><strong>itfal</strong> 孩子</td></tr><tr><td><strong>għaxra</strong> 十</td><td><strong>għaxar / għaxart</strong></td><td><strong>għaxar lapsijiet</strong> 十支铅笔<br><strong>għaxar</strong> 十<br><strong>lapsijiet</strong> 铅笔</td><td><strong>għaxart itfal</strong> 十个孩子<br><strong>għaxart</strong> 十<br><strong>itfal</strong> 孩子</td></tr></tbody></table><p>原表还逐行列出 <code>żewġ karti</code> 至 <code>għaxar karti</code>，以及 <code>tliet lapsijiet</code> 至 <code>disa’ lapsijiet</code>。词义和变化遵循同一表格，不另造不同规则。</p><p><strong>这里的 -t 形式用于本页所示 itfal 等元音开头环境，不宜只看字母表就推广到所有词；下一页 ħwienet / iħwienet 等还涉及名词前置元音。</strong></p><h3 id="_11–19-连接形式-il-名词用单数" tabindex="-1">11–19：连接形式 -il，名词用单数 <a class="header-anchor" href="#_11–19-连接形式-il-名词用单数" aria-label="Permalink to &quot;11–19：连接形式 -il，名词用单数&quot;">​</a></h3><table><thead><tr><th>数字</th><th>数词 + 名词</th><th>中文与拆解</th></tr></thead><tbody><tr><td>11</td><td><strong>ħdax-il lapes</strong></td><td>十一支铅笔。<br><strong>ħdax-il</strong> 十一（接名词）<br><strong>lapes</strong> 铅笔（单数形式）</td></tr><tr><td>12</td><td><strong>tnax-il karta</strong></td><td>十二张纸。<br><strong>tnax-il</strong> 十二<br><strong>karta</strong> 纸（单数形式）</td></tr><tr><td>13</td><td><strong>tlettax-il lapes</strong></td><td>十三支铅笔。<br><strong>tlettax-il</strong> 十三<br><strong>lapes</strong> 铅笔</td></tr><tr><td>14</td><td><strong>erbatax-il karta</strong></td><td>十四张纸。<br><strong>erbatax-il</strong> 十四<br><strong>karta</strong> 纸</td></tr><tr><td>15</td><td><strong>ħmistax-il lapes</strong></td><td>十五支铅笔。<br><strong>ħmistax-il</strong> 十五<br><strong>lapes</strong> 铅笔</td></tr><tr><td>16</td><td><strong>sittax-il karta</strong></td><td>十六张纸。<br><strong>sittax-il</strong> 十六<br><strong>karta</strong> 纸</td></tr><tr><td>17</td><td><strong>sbatax-il lapes</strong></td><td>十七支铅笔。<br><strong>sbatax-il</strong> 十七<br><strong>lapes</strong> 铅笔</td></tr><tr><td>18</td><td><strong>tmintax-il karta</strong></td><td>十八张纸。<br><strong>tmintax-il</strong> 十八<br><strong>karta</strong> 纸</td></tr><tr><td>19</td><td><strong>dsatax-il lapes</strong></td><td>十九支铅笔。<br><strong>dsatax-il</strong> 十九<br><strong>lapes</strong> 铅笔</td></tr><tr><td>20</td><td><strong>għoxrin karta</strong></td><td>二十张纸；没有额外 -il。<br><strong>għoxrin</strong> 二十<br><strong>karta</strong> 纸（单数形式）</td></tr></tbody></table><p>教材每行均列 <code>lapes</code>、<code>karta</code> 和 <code>tifel u tifla</code> 三列；数词换用相应行的形式即可，原文全部形式见录入稿。</p><ul><li><strong>tifel</strong> 男孩（单数）。</li><li><strong>u</strong> 和。</li><li><strong>tifla</strong> 女孩（单数）。</li><li><strong>ħdax-il tifel u tifla</strong> 按教材用于示范十一人的男／女孩计数表达；不能孤立地当成数学公式来决定男女各有多少人。</li></ul><p><strong>关键对照：</strong> <code>tliet bajdiet</code> 三个鸡蛋，但 <code>tnax-il gallettina</code> 十二块饼干；不是名词前有数字就一律用复数。</p><hr><h2 id="_15-题目逐词理解" tabindex="-1">15 题目逐词理解 <a class="header-anchor" href="#_15-题目逐词理解" aria-label="Permalink to &quot;15 题目逐词理解&quot;">​</a></h2><p><strong>Imla l-vojt bin-numru t-tajjeb skont dak li hemm fil-parentesi u aqta’ linja taħt in-nom li jixraq.</strong></p><p>中文：根据括号中的数字填入正确数词，并在合适的名词下面画线。</p><ul><li><strong>imla l-vojt</strong> 填空。</li><li><strong>bin-numru t-tajjeb</strong> 用正确的数词。</li><li><strong>skont</strong> 根据。</li><li><strong>dak li hemm</strong> 其中已有的内容。</li><li><strong>fil-parentesi</strong> 在括号里。</li><li><strong>u</strong> 并且。</li><li><strong>aqta’ linja</strong> 画线（整组表达）。</li><li><strong>taħt</strong> 在……下面。</li><li><strong>in-nom</strong> 名词。</li><li><strong>li jixraq</strong> 合适的。</li></ul><p>示例：<strong>Xtrajt tliet lanġasiet.</strong> 我买了三个梨。</p><ul><li><strong>xtrajt</strong> 我买了。</li><li><strong>tliet</strong> 三。</li><li><strong>lanġasiet</strong> 梨（可数复数）。</li></ul><h3 id="全部参考答案" tabindex="-1">全部参考答案 <a class="header-anchor" href="#全部参考答案" aria-label="Permalink to &quot;全部参考答案&quot;">​</a></h3><p>下列句子直接保留正确选项，省去应划掉的词形。</p><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Jien għandi għoxrin sena.</td><td>我二十岁。<br><strong>jien</strong> 我<br><strong>għandi</strong> 我有<br><strong>għoxrin</strong> 二十<br><strong>sena</strong> 年（这里用单数形式，不选 snin）。</td></tr><tr><td>2. Fit-tiġrija konna ħdax-il tifel u tifla.</td><td>参加比赛的我们共有十一名男孩和女孩，按教材表达。<br><strong>fit-tiġrija</strong> 在比赛／赛跑中<br><strong>konna</strong> 我们当时是、有<br><strong>ħdax-il</strong> 十一（接名词）<br><strong>tifel u tifla</strong> 男孩与女孩；按原题选此组，不选 tfal。</td></tr><tr><td>3. Oħti ż-żgħira għandha ħames snin.</td><td>我妹妹五岁。<br><strong>oħti</strong> 我的姐妹<br><strong>ż-żgħira</strong> 小的、年幼的（这里是妹妹）<br><strong>għandha</strong> 她有<br><strong>ħames</strong> 五（名词前）<br><strong>snin</strong> 年（复数）。</td></tr><tr><td>4. Kilt tuffieħa waħda u żewġ larinġiet.</td><td>我吃了一个苹果和两个橙子。<br><strong>kilt</strong> 我吃了<br><strong>tuffieħa</strong> 一个苹果（阴性）<br><strong>waħda</strong> 一（阴性，放在名词后）<br><strong>u</strong> 和<br><strong>żewġ</strong> 两<br><strong>larinġiet</strong> 橙子（可数复数），不选集合 larinġ。</td></tr><tr><td>5. Morna nduru għaxart iħwienet u xtrajna erbat ilbiesi.</td><td>我们逛了十家商店，买了四条裙子。<br><strong>morna</strong> 我们去了<br><strong>nduru</strong> 我们四处逛<br><strong>għaxart</strong> 十（此处 -t 形式）<br><strong>iħwienet</strong> 商店（复数，带前置 i）<br><strong>u</strong> 和<br><strong>xtrajna</strong> 我们买了<br><strong>erbat</strong> 四（接元音形式）<br><strong>ilbiesi</strong> 连衣裙（复数；开头 il- 是词形的一部分，不是本题另加的定冠词）。</td></tr><tr><td>6. Id-dar għandna tliet għasafar u tlitt iklieb.</td><td>我们家有三只鸟和三只狗。<br><strong>id-dar</strong> 在家<br><strong>għandna</strong> 我们有<br><strong>tliet</strong> 三<br><strong>għasafar</strong> 鸟（复数）<br><strong>u</strong> 和<br><strong>tlitt</strong> 三（此处接前置元音形式）<br><strong>iklieb</strong> 狗（klieb 的带前置 i 形式）。</td></tr><tr><td>7. Kien hemm ħmistax-il persuna fil-kju.</td><td>队伍里有十五个人。<br><strong>kien hemm</strong> 当时有<br><strong>ħmistax-il</strong> 十五<br><strong>persuna</strong> 人（这里用单数形式）<br><strong>fil-kju</strong> 在队伍里。</td></tr><tr><td>8. Ilni noqgħod hawn Malta għal dawn l-aħħar seba’ snin.</td><td>过去七年我一直住在马耳他。<br><strong>ilni</strong> 我已经持续……<br><strong>noqgħod</strong> 我住<br><strong>hawn</strong> 这里<br><strong>Malta</strong> 马耳他<br><strong>għal</strong> 持续<br><strong>dawn l-aħħar</strong> 过去这些、最近这些<br><strong>seba’</strong> 七（名词前）<br><strong>snin</strong> 年（复数）。</td></tr><tr><td>9. F’Ġunju rrid nagħmel tmien eżamijiet.</td><td>六月我要参加八场考试。<br><strong>f’Ġunju</strong> 在六月<br><strong>rrid</strong> 我要／必须<br><strong>nagħmel</strong> 我做、我参加<br><strong>tmien</strong> 八（接名词）<br><strong>eżamijiet</strong> 考试（复数）。</td></tr><tr><td>10. Jien għandi disa’ kuġini. Erbgħa minnhom huma ikbar minni.</td><td>我有九个堂／表亲，其中四个比我大。<br><strong>jien</strong> 我<br><strong>għandi</strong> 我有<br><strong>disa’</strong> 九（接名词）<br><strong>kuġini</strong> 堂／表亲（复数）<br><strong>erbgħa</strong> 四（独立代指人）<br><strong>minnhom</strong> 他们之中<br><strong>huma</strong> 是<br><strong>ikbar</strong> 更大、年龄更大<br><strong>minni</strong> 比我。</td></tr></tbody></table><p>第 5、6 题考查的正是 <code>iħwienet / ilbiesi / iklieb</code> 与数词衔接时的形式，不应为了匹配孤立词典词头而删去这些 i。</p><hr><h2 id="_16-数词是否直接修饰名词" tabindex="-1">16 数词是否直接修饰名词 <a class="header-anchor" href="#_16-数词是否直接修饰名词" aria-label="Permalink to &quot;16 数词是否直接修饰名词&quot;">​</a></h2><p><strong>X’inhi d-differenza bejn dawn?</strong> 这些形式有什么区别？</p><ul><li><strong>x’inhi</strong> 是什么（阴性）。</li><li><strong>d-differenza</strong> 区别。</li><li><strong>bejn</strong> 在……之间。</li><li><strong>dawn</strong> 这些。</li></ul><table><thead><tr><th>独立形式</th><th>名词前形式</th><th>差别</th></tr></thead><tbody><tr><td><strong>erbgħa</strong> 四</td><td><strong>erba’</strong> 四个……</td><td>独立读数／代指四个，对比直接修饰名词</td></tr><tr><td><strong>sebgħa</strong> 七</td><td><strong>seba’</strong> 七个……</td><td>同上</td></tr><tr><td><strong>disgħa</strong> 九</td><td><strong>disa’</strong> 九个……</td><td>同上</td></tr><tr><td><strong>ħamsa</strong> 五</td><td><strong>ħames</strong> 五个……</td><td>教材用这组更明显的词形帮助判断</td></tr></tbody></table><h3 id="说明与例句逐句解析" tabindex="-1">说明与例句逐句解析 <a class="header-anchor" href="#说明与例句逐句解析" aria-label="Permalink to &quot;说明与例句逐句解析&quot;">​</a></h3><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Ħares ftit lejn l-aħħar sentenza tal-eżerċizzju li għadda u qabbilha ma’ ta’ taħtha.</td><td>看一下上一个练习的最后一句，与下面那句比较。<br><strong>ħares lejn</strong> 看<br><strong>ftit</strong> 一下<br><strong>l-aħħar sentenza</strong> 最后一句<br><strong>tal-eżerċizzju</strong> 练习的<br><strong>li għadda</strong> 刚过去的、上一个<br><strong>u</strong> 并且<br><strong>qabbilha</strong> 把它比较（-ha 指 sentenza）<br><strong>ma’</strong> 和<br><strong>ta’ taħtha</strong> 它下面那一个。</td></tr><tr><td>Jien għandi disa’ kuġini. Erbgħa minnhom huma ikbar minni.</td><td>我有九个堂／表亲，其中四个比我大。<br><strong>jien għandi</strong> 我有<br><strong>disa’</strong> 九（直接修饰名词）<br><strong>kuġini</strong> 堂／表亲<br><strong>erbgħa</strong> 四（后面没有直接接被计数名词）<br><strong>minnhom</strong> 其中<br><strong>huma</strong> 是<br><strong>ikbar</strong> 更大<br><strong>minni</strong> 比我。</td></tr><tr><td>Jien għandi ħames kuġini. Ħamsa minnhom huma ikbar minni.</td><td>我有五个堂／表亲，五个都比我大。<br><strong>jien għandi</strong> 我有<br><strong>ħames</strong> 五（名词前）<br><strong>kuġini</strong> 堂／表亲<br><strong>ħamsa</strong> 五（独立）<br><strong>minnhom</strong> 其中<br><strong>huma ikbar minni</strong> 比我大。</td></tr><tr><td>X’qed tinnota? Uża n-numru ħamsa (5) bħala l-mudell ta’ kif trid tikteb in-numri erbgħa (4), sebgħa (7) u disgħa (9).</td><td>你注意到了什么？用“五”的变化作为写“四、七、九”的参考模式。<br><strong>x’qed tinnota</strong> 你注意到什么<br><strong>uża</strong> 使用<br><strong>n-numru</strong> 数字<br><strong>ħamsa</strong> 五<br><strong>bħala</strong> 作为<br><strong>l-mudell</strong> 模式<br><strong>ta’ kif</strong> 关于如何<br><strong>trid tikteb</strong> 你应当写<br><strong>in-numri</strong> 这些数字<br><strong>erbgħa</strong> 四<br><strong>sebgħa</strong> 七<br><strong>u</strong> 和<br><strong>disgħa</strong> 九。</td></tr></tbody></table><p>可作答：<strong>In-numru jinbidel meta jiġi qabel nom.</strong> 数词放在名词前时会变化。</p><ul><li><strong>in-numru</strong> 数词。</li><li><strong>jinbidel</strong> 发生变化。</li><li><strong>meta</strong> 当。</li><li><strong>jiġi</strong> 它来到、它出现。</li><li><strong>qabel</strong> 在……之前。</li><li><strong>nom</strong> 名词。</li></ul><h3 id="b-全部填空参考答案" tabindex="-1">B. 全部填空参考答案 <a class="header-anchor" href="#b-全部填空参考答案" aria-label="Permalink to &quot;B. 全部填空参考答案&quot;">​</a></h3><p><strong>Ikteb in-numru t-tajjeb.</strong> 写出正确的数字形式。</p><ul><li><strong>ikteb</strong> 写。</li><li><strong>in-numru</strong> 数字。</li><li><strong>t-tajjeb</strong> 正确的。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Xtrajt seba’ kotba, erbgħa minnhom huma bil-Malti.</td><td>我买了七本书，其中四本是马耳他语的。<br><strong>xtrajt</strong> 我买了<br><strong>seba’</strong> 七（接名词）<br><strong>kotba</strong> 书（复数）<br><strong>erbgħa</strong> 四（独立代指书）<br><strong>minnhom</strong> 其中<br><strong>huma</strong> 是<br><strong>bil-Malti</strong> 用马耳他语。</td></tr><tr><td>2. Kemm kontu nies ilbieraħ? Ilbieraħ konna disgħa.</td><td>昨天你们有多少人？昨天我们有九个人。<br><strong>kemm</strong> 多少<br><strong>kontu</strong> 你们当时是／有<br><strong>nies</strong> 人<br><strong>ilbieraħ</strong> 昨天<br><strong>konna</strong> 我们当时是／有<br><strong>disgħa</strong> 九（独立数词）。</td></tr><tr><td>3. Martha hi erba’ snin ikbar minni.</td><td>Martha 比我大四岁。<br><strong>Martha</strong> 人名<br><strong>hi</strong> 她是<br><strong>erba’</strong> 四（接名词）<br><strong>snin</strong> 年<br><strong>ikbar</strong> 更大<br><strong>minni</strong> 比我。</td></tr><tr><td>4. Xtaqt nixtri disa’ pitazzi imma tal-ħanut kellu biss sebgħa.</td><td>我想买九本练习本，可店主只有七本。<br><strong>xtaqt</strong> 我想要（过去）<br><strong>nixtri</strong> 我买<br><strong>disa’</strong> 九（接名词）<br><strong>pitazzi</strong> 练习本、笔记本（复数）<br><strong>imma</strong> 但是<br><strong>tal-ħanut</strong> 店主<br><strong>kellu</strong> 他有（过去）<br><strong>biss</strong> 只有<br><strong>sebgħa</strong> 七（独立代指本子）。</td></tr><tr><td>5. Is-sena l-oħra żort seba’ pajjiżi, erbgħa minnhom huma fl-Ewropa.</td><td>去年我去过七个国家，其中四个在欧洲。<br><strong>is-sena l-oħra</strong> 去年<br><strong>żort</strong> 我访问过<br><strong>seba’</strong> 七（名词前）<br><strong>pajjiżi</strong> 国家（复数）<br><strong>erbgħa</strong> 四（独立）<br><strong>minnhom</strong> 其中<br><strong>huma</strong> 是、位于<br><strong>fl-Ewropa</strong> 在欧洲。</td></tr></tbody></table><hr><h2 id="_17-双数说明逐句解析" tabindex="-1">17 双数说明逐句解析 <a class="header-anchor" href="#_17-双数说明逐句解析" aria-label="Permalink to &quot;17 双数说明逐句解析&quot;">​</a></h2><table><thead><tr><th>原句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Iktar numri... L-Għadd Imtenni</td><td>更多数量表达……双数。<br><strong>iktar</strong> 更多<br><strong>numri</strong> 数字<br><strong>l-għadd</strong> 数、语法上的数<br><strong>imtenni</strong> 成双的、重复的。</td></tr><tr><td>Dan jintuża meta jkollna tnejn (2) minn xi nom.</td><td>当某一名词所指的东西有两个时使用这种形式。<br><strong>dan</strong> 这个<br><strong>jintuża</strong> 被使用<br><strong>meta</strong> 当<br><strong>jkollna</strong> 我们有<br><strong>tnejn</strong> 两个<br><strong>minn</strong> 从……中、属于……<br><strong>xi nom</strong> 某个名词。</td></tr><tr><td>Dan jispiċċa bl-ittri -ejn jew -ajn.</td><td>这种形式以 -ejn 或 -ajn 结尾。<br><strong>dan</strong> 这个形式<br><strong>jispiċċa</strong> 以……结束<br><strong>bl-ittri</strong> 以这些字母<br><strong>-ejn</strong> 双数词尾之一<br><strong>jew</strong> 或者<br><strong>-ajn</strong> 双数词尾之一。</td></tr><tr><td>Agħti l-għadd imtenni ta’ dawn in-nomi.</td><td>写出这些名词的双数形式。<br><strong>agħti</strong> 给出<br><strong>l-għadd imtenni</strong> 双数<br><strong>ta’</strong> ……的<br><strong>dawn in-nomi</strong> 这些名词。</td></tr></tbody></table><p>双数不能对所有名词机械加 <code>-ejn</code>；有词干变化及固定形式。例如 <code>sena → sentejn</code>，不是把 sena 原样加词尾。</p><h3 id="a-16-项参考答案" tabindex="-1">A. 16 项参考答案 <a class="header-anchor" href="#a-16-项参考答案" aria-label="Permalink to &quot;A. 16 项参考答案&quot;">​</a></h3><table><thead><tr><th>题号</th><th>单数 → 双数</th><th>中文与词形提示</th></tr></thead><tbody><tr><td>1</td><td><strong>jum → jumejn</strong></td><td>一天 → 两天；原题已给。</td></tr><tr><td>2</td><td><strong>id → idejn</strong></td><td>一只手 → 两只手。</td></tr><tr><td>3</td><td><strong>ħadd → ħaddejn</strong></td><td>一侧脸颊 → 双颊；与 Ħadd“星期日”、代词 ħadd“任何人／没有人”区分。</td></tr><tr><td>4</td><td><strong>elf → elfejn</strong></td><td>一千 → 两千。</td></tr><tr><td>5</td><td><strong>għajn → għajnejn</strong></td><td>一只眼睛 → 两只眼睛。</td></tr><tr><td>6</td><td><strong>sieq → saqajn</strong></td><td>一只脚／一条腿 → 双脚／双腿。</td></tr><tr><td>7</td><td><strong>driegħ → dirgħajn</strong></td><td>一条手臂 → 两条手臂。</td></tr><tr><td>8</td><td><strong>pass → passejn</strong></td><td>一步 → 两步。</td></tr><tr><td>9</td><td><strong>spalla → spallejn</strong></td><td>一个肩膀 → 双肩。</td></tr><tr><td>10</td><td><strong>rkoppa → rkopptejn</strong></td><td>一只膝盖 → 双膝。</td></tr><tr><td>11</td><td><strong>siegħa → sagħtejn</strong></td><td>一小时 → 两小时。</td></tr><tr><td>12</td><td><strong>darba → darbtejn</strong></td><td>一次 → 两次。</td></tr><tr><td>13</td><td><strong>ġimgħa → ġimagħtejn</strong></td><td>一周 → 两周。</td></tr><tr><td>14</td><td><strong>wiżna → wiżintejn</strong></td><td>一个旧重量单位 wiżna → 两个单位；词干插入 i，不直接拼成 wiżntejn。</td></tr><tr><td>15</td><td><strong>sena → sentejn</strong></td><td>一年 → 两年。</td></tr><tr><td>16</td><td><strong>kelma → kelmtejn</strong></td><td>一个词 → 两个词；也可用于“说几句话”等习语，须按语境。</td></tr></tbody></table><h3 id="b-完整补全与逐词解析" tabindex="-1">B. 完整补全与逐词解析 <a class="header-anchor" href="#b-完整补全与逐词解析" aria-label="Permalink to &quot;B. 完整补全与逐词解析&quot;">​</a></h3><p><strong>Poġġi l-kliem li jinsab fil-parentesi, fl-għadd imtenni.</strong> 把括号里的词变为双数。</p><ul><li><strong>poġġi</strong> 放入、写入。</li><li><strong>l-kliem</strong> 词语。</li><li><strong>li jinsab</strong> 所在的、出现的。</li><li><strong>fil-parentesi</strong> 在括号中。</li><li><strong>fl-għadd imtenni</strong> 变为双数形式。</li></ul><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Kellu ħsieb li joqgħod ġimagħtejn Londra u minflok qagħad xahrejn.</td><td>他本来打算在伦敦待两周，结果待了两个月。<br><strong>kellu ħsieb</strong> 他原本打算<br><strong>li</strong> 引导从句<br><strong>joqgħod</strong> 他停留、居住<br><strong>ġimagħtejn</strong> 两周<br><strong>Londra</strong> 伦敦<br><strong>u</strong> 而<br><strong>minflok</strong> 代替、结果反而<br><strong>qagħad</strong> 他待了<br><strong>xahrejn</strong> 两个月（xahar 的双数）。</td></tr><tr><td>2. Ix-xofftejn, il-widnejn u l-għajnejn huma partijiet sensittivi tal-wiċċ.</td><td>双唇、双耳和双眼是脸部敏感的部位。<br><strong>ix-xofftejn</strong> 双唇（xoffa → xofftejn）<br><strong>il-widnejn</strong> 双耳（widna → widnejn）<br><strong>u</strong> 和<br><strong>l-għajnejn</strong> 双眼<br><strong>huma</strong> 是<br><strong>partijiet</strong> 部位<br><strong>sensittivi</strong> 敏感的（复数）<br><strong>tal-wiċċ</strong> 脸的。</td></tr><tr><td>3. Kien hemm mal-mitejn ruħ fil-gallariji u mal-elfejn ruħ fit-toroq jistennew il-wasla tal-President.</td><td>约有两百人在阳台上、两千人在街道上，等候总统到来。<br><strong>kien hemm</strong> 当时有<br><strong>mal-mitejn</strong> 约两百（mitt → mitejn；连冠词按整词重写）<br><strong>ruħ</strong> 人、人数单位<br><strong>fil-gallariji</strong> 在阳台上（复数）<br><strong>u</strong> 和<br><strong>mal-elfejn</strong> 约两千<br><strong>fit-toroq</strong> 在街道上<br><strong>jistennew</strong> 他们等待<br><strong>il-wasla</strong> 到来<br><strong>tal-President</strong> 总统的。</td></tr><tr><td>4. Ommi xtrat ratlejn basal u wiżintejn patata.</td><td>妈妈买了两 ratal 洋葱和两 wiżna 土豆。<br><strong>ommi</strong> 我的母亲<br><strong>xtrat</strong> 她买了<br><strong>ratlejn</strong> ratal 的双数（两个旧重量单位）<br><strong>basal</strong> 洋葱<br><strong>u</strong> 和<br><strong>wiżintejn</strong> wiżna 的双数<br><strong>patata</strong> 土豆。</td></tr><tr><td>5. Sentejn ilu sifirna darbtejn.</td><td>两年前我们出国旅行过两次。<br><strong>sentejn</strong> 两年<br><strong>ilu</strong> ……以前（与前面时间组成“……前”）<br><strong>sifirna</strong> 我们出国／旅行了<br><strong>darbtejn</strong> 两次。</td></tr><tr><td>6. Il-ħajjata ħaditlu l-qies tal-ispallejn u t-tul tal-idejn biex tħitlu ġakketta.</td><td>女裁缝量了他的双肩尺寸和双手臂长度，以便给他缝夹克。<br><strong>il-ħajjata</strong> 女裁缝<br><strong>ħaditlu</strong> 她给他取了／量了<br><strong>l-qies</strong> 尺寸<br><strong>tal-ispallejn</strong> 双肩的（按原题 ispalla 词形）<br><strong>u</strong> 和<br><strong>t-tul</strong> 长度<br><strong>tal-idejn</strong> 双手／手臂的；这里按原题 id 转双数<br><strong>biex</strong> 为了<br><strong>tħitlu</strong> 她缝给他<br><strong>ġakketta</strong> 夹克。</td></tr></tbody></table><p>第 6 题按教材 <code>id</code> 作答；若要精确表达“手臂长度”，实际描述可用 <code>dirgħajn</code>，但那是措辞改写，不是本题括号词的双数答案。</p><p>词形复核来源：<a href="https://en.wiktionary.org/wiki/%C4%A7add" target="_blank" rel="noreferrer">ħadd</a>、<a href="https://en.wiktionary.org/wiki/ratal" target="_blank" rel="noreferrer">ratal</a>、<a href="https://en.wiktionary.org/wiki/wi%C5%BCna" target="_blank" rel="noreferrer">wiżna</a>。这里只据词条核对词义与屈折形式，不将词典例句作为教材原文。</p><hr><h2 id="_18-数量表达与原例句" tabindex="-1">18 数量表达与原例句 <a class="header-anchor" href="#_18-数量表达与原例句" aria-label="Permalink to &quot;18 数量表达与原例句&quot;">​</a></h2><p><strong>L-Avverbji tal-Kwantità – Kemm?</strong> 数量副词——多少？</p><ul><li><strong>l-avverbji</strong> 副词。</li><li><strong>tal-kwantità</strong> 数量的。</li><li><strong>kemm</strong> 多少、多么。</li></ul><p>教材将这些词集中在“数量副词”下学习，实际有些词也可作代词、限定数量的表达，须结合句中作用判断。</p><table><thead><tr><th>词语与原例句</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Bilkemm — Bilkemm ilħaqt poġġejt bilqiegħda llum!</td><td>几乎不／勉强——今天我几乎没来得及坐下来！<br><strong>bilkemm</strong> 几乎不、勉强<br><strong>ilħaqt</strong> 我来得及<br><strong>poġġejt</strong> 我坐下了<br><strong>bilqiegħda</strong> 坐着、就座<br><strong>llum</strong> 今天。</td></tr><tr><td>Biss — Agħtini erbgħa biss, mhux iktar.</td><td>只有——只给我四个，不要更多。<br><strong>biss</strong> 只<br><strong>agħtini</strong> 给我<br><strong>erbgħa</strong> 四个（独立）<br><strong>mhux</strong> 不、不是<br><strong>iktar</strong> 更多。</td></tr><tr><td>Biżżejjed — Daqshekk biżżejjed!</td><td>足够——这些就够了！<br><strong>biżżejjed</strong> 足够<br><strong>daqshekk</strong> 这么多、到这个程度。</td></tr><tr><td>Ftit / naqra — Jien niekol ftit.</td><td>一点——我吃得少。<br><strong>ftit</strong> 一点、少量<br><strong>naqra</strong> 一点（本页为数量表达，不是动词“我读”）<br><strong>jien</strong> 我<br><strong>niekol</strong> 我吃。</td></tr><tr><td>Ftit li xejn — Lil Toni rajtu ftit li xejn.</td><td>很少，几乎没有——我几乎没见到 Toni。<br><strong>ftit li xejn</strong> 极少、几乎没有（固定短语）<br><strong>lil Toni</strong> Toni（前置宾语）<br><strong>rajtu</strong> 我见到他了（rajt + 宾语 -u）。</td></tr><tr><td>Ħafna — Tina tħobb tgħum ħafna!</td><td>很多／很——Tina 很喜欢游泳！也可按语境理解“常游泳”。<br><strong>ħafna</strong> 很多、很<br><strong>Tina</strong> 人名<br><strong>tħobb</strong> 她喜欢<br><strong>tgħum</strong> 她游泳。</td></tr><tr><td>Iktar / iżjed — It-tarbija riedet iktar ħalib.</td><td>更多——宝宝还想要更多牛奶。<br><strong>iktar / iżjed</strong> 更多<br><strong>it-tarbija</strong> 婴儿<br><strong>riedet</strong> 她／它想要（阴性）<br><strong>ħalib</strong> 牛奶。</td></tr><tr><td>Inqas — Għandi inqas flus minnek.</td><td>更少——我的钱比你少。<br><strong>inqas</strong> 更少<br><strong>għandi</strong> 我有<br><strong>flus</strong> 钱<br><strong>minnek</strong> 比你。</td></tr><tr><td>Kollox — Għidli kollox!</td><td>全部——把所有事情告诉我！<br><strong>kollox</strong> 一切、全部<br><strong>għidli</strong> 告诉我。</td></tr><tr><td>Żejjed — Baqa’ ż-żejjed u rfajtu għal għada.</td><td>多余的／剩下的——有多余的剩下来，我把它收好留到明天。<br><strong>żejjed</strong> 多余的<br><strong>baqa’</strong> 剩下了<br><strong>ż-żejjed</strong> 剩余部分（名词化）<br><strong>u</strong> 并且<br><strong>rfajtu</strong> 我把它收好了（rfajt + -u）<br><strong>għal għada</strong> 留到明天。</td></tr></tbody></table><h3 id="八题填空参考答案" tabindex="-1">八题填空参考答案 <a class="header-anchor" href="#八题填空参考答案" aria-label="Permalink to &quot;八题填空参考答案&quot;">​</a></h3><p><strong>Imla l-vojt bl-avverbji tal-kwantità.</strong> 用数量副词填空。</p><ul><li><strong>imla l-vojt</strong> 填空。</li><li><strong>bl-avverbji</strong> 用副词。</li><li><strong>tal-kwantità</strong> 表数量的。</li></ul><p>以下是一组语法与语境通顺的参考答案，允许重复用词；原题未说明“每词限用一次”。</p><table><thead><tr><th>补全句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>1. Il-lejl li għadda, bilkemm irqadt.</td><td>昨晚我几乎没睡。<br><strong>il-lejl</strong> 夜晚<br><strong>li għadda</strong> 刚过去的<br><strong>bilkemm</strong> 几乎不<br><strong>irqadt</strong> 我睡了。</td></tr><tr><td>2. Illum inħossni ħafna aħjar.</td><td>今天我感觉好多了。<br><strong>illum</strong> 今天<br><strong>inħossni</strong> 我觉得自己、我感觉<br><strong>ħafna</strong> 很多（加强比较程度）<br><strong>aħjar</strong> 更好。</td></tr><tr><td>3. Jien għandi ftit ħbieb.</td><td>我有几个朋友／我的朋友不多。<br><strong>jien</strong> 我<br><strong>għandi</strong> 我有<br><strong>ftit</strong> 少量、几个<br><strong>ħbieb</strong> 朋友（复数）。</td></tr><tr><td>4. Nixtieq li niltaqgħu iżjed drabi.</td><td>我希望我们能更常见面。<br><strong>nixtieq</strong> 我希望<br><strong>li</strong> 引导从句<br><strong>niltaqgħu</strong> 我们见面<br><strong>iżjed</strong> 更多<br><strong>drabi</strong> 次数。</td></tr><tr><td>5. Ilbieraħ ħadna ħafna gost!</td><td>昨天我们玩得很开心！<br><strong>ilbieraħ</strong> 昨天<br><strong>ħadna</strong> 我们获得、享受了<br><strong>ħafna</strong> 很多、很<br><strong>gost</strong> 乐趣；ħadna gost 为“我们玩得开心”。</td></tr><tr><td>6. Kollox kien tajjeb u tgħidx kemm kilna!</td><td>一切都很好，而且我们吃了好多！<br><strong>kollox</strong> 一切<br><strong>kien</strong> 当时是<br><strong>tajjeb</strong> 好的<br><strong>u</strong> 和<br><strong>tgħidx</strong> 别说（否定命令式）<br><strong>kemm</strong> 多少、多么<br><strong>kilna</strong> 我们吃了；tgħidx kemm 为感叹用法，意为“可真不少”。</td></tr><tr><td>7. Ma kien fadal xejn iżjed.</td><td>再没有剩余的东西了。<br><strong>ma</strong> 否定标记<br><strong>kien fadal</strong> 当时还剩<br><strong>xejn</strong> 什么也没有；与 ma 呼应<br><strong>iżjed</strong> 更多、再有。</td></tr><tr><td>8. Xrobna ftit inbid aħmar.</td><td>我们喝了一点红葡萄酒。<br><strong>xrobna</strong> 我们喝了<br><strong>ftit</strong> 少量<br><strong>inbid</strong> 葡萄酒<br><strong>aħmar</strong> 红色的。</td></tr></tbody></table><p>第 7 题也可参考 <strong>Ma kien fadal xejn żejjed.</strong>（没有多余的剩下。）</p><ul><li><strong>żejjed</strong> 多余的。</li></ul><h2 id="复习要点" tabindex="-1">复习要点 <a class="header-anchor" href="#复习要点" aria-label="Permalink to &quot;复习要点&quot;">​</a></h2><ol><li>购物礼貌用语：<strong>agħtini</strong>（给我）、<strong>jekk jogħġbok</strong>（请）、<strong>x’għandi nagħtik?</strong>（我该付多少钱？）、<strong>bqija</strong>（找零）。</li><li>配料表达：<strong>gramma</strong>（克）、<strong>millilitru</strong>（毫升）、<strong>kuċċarina</strong>（茶匙）、<strong>nofs</strong>（一半）、<strong>ftit</strong>（少许）。</li><li>食谱常用命令：<strong>itfa’</strong>（放入）、<strong>ħawwad</strong>（搅拌）、<strong>żid</strong>（添加）、<strong>farrak</strong>（弄碎）、<strong>ifrex</strong>（铺开）、<strong>aħmi</strong>（烘烤）。</li><li>穿着一致：<strong>liebes</strong>（男）、<strong>liebsa</strong>（女）、<strong>libsin / lebsin</strong>（复数）；颜色跟所修饰名词配合，不跟穿衣者性别机械配合。</li><li>数词结构：<strong>erbgħa</strong> 独立读“四”，<strong>erba’ snin</strong> 表“四年”；<strong>tliet kotba</strong> 三本书，<strong>ħdax-il ktieb</strong> 十一本书，<strong>għoxrin ktieb</strong> 二十本书。</li><li>双数作为整词记：<strong>jumejn</strong> 两天、<strong>sagħtejn</strong> 两小时、<strong>ġimagħtejn</strong> 两周、<strong>xahrejn</strong> 两个月、<strong>sentejn</strong> 两年、<strong>darbtejn</strong> 两次。</li></ol>',212),a=[g];function i(d,l,e,b,u,m){return r(),n("div",null,a)}const j=t(s,[["render",i]]);export{k as __pageData,j as default};
